-- =============================================================================
-- 551 — LE CAHIER D'EXERCICES DE TLE (partie 23)
--
-- FICHIER GÉNÉRÉ par scripts/exercices-sql.ts depuis contenu/exercices/Tle/ :
-- ne pas l'éditer à la main, corriger le JSON et régénérer :
--   node node_modules/jiti/lib/jiti-cli.mjs scripts/exercices-sql.ts --num 551 --niveau Tle --fichiers anglais.jumelles,arts-plastiques.jumelles --suffixe 23 > supabase/contenu/551_exercices_tle_23.sql
--
-- 81 exercices écrits et relus : pour chaque chapitre, trois exercices faits
-- comme une page de manuel (★ facile, ★★ moyen, ★★★ plus corsé), avec leurs
-- documents (cartes, graphiques, textes, schémas…) et leurs questions. Le
-- contenu public va dans `exercices`, les réponses et explications dans
-- `exercices_cles` (qu'aucun élève ne lit). Gemmes et XP selon les étoiles
-- (5/10/15 gemmes, 20/35/50 XP), réglables ensuite en base.
--
--   anglais.jumelles        72 exercices · 24 chapitres
--   arts-plastiques.jumelles   9 exercices · 3 chapitres
--
-- L'identifiant d'un exercice est dérivé de (chapitre, position) : rejouer ce
-- fichier met les exercices à jour sans doublon, et garde les résultats des
-- élèves. Un exercice dont le chapitre n'existe pas en base est sauté.
--
-- PRÉREQUIS : 372 (le cahier). Idempotent. À exécuter à la main dans :
-- Supabase Dashboard → SQL Editor → New query → Run.
-- =============================================================================

DROP TABLE IF EXISTS pg_temp.exercices_seed;
CREATE TEMP TABLE exercices_seed AS
SELECT md5('exercice:' || v.chapter_id::text || ':' || v.position::text)::uuid AS id, v.*
FROM (VALUES
  ('04e22a95-7692-5dbd-8be7-4d2bb117d749'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Sam se présente","competence":"comprendre-langue","situation":"Sam se présente à sa nouvelle classe. Repère les mots qui parlent de temps.","documents":[{"id":"texte","type":"texte","genre":"lettre","titre":"Hi, I’m Sam","blocs":["Hi, I’m Sam. I have lived in Leeds since 2019. I have played football for four years. I joined my club two years ago. I met my best friend during the summer camp."],"source":"Texte écrit pour l’exercice"}],"questions":[{"enonce":"Touche le mot qui introduit un point de départ.","aide":"Il est suivi d’une année.","type":"zone","document":"texte","multiple":false},{"enonce":"Touche le mot qui se place après la durée et date un fait passé.","aide":"On dit « two years ___ », pas « ___ two years ».","type":"zone","document":"texte","multiple":false},{"enonce":"Relie chaque mot à son sens.","aide":"Relis la présentation de Sam.","type":"association","gauche":[{"id":"g0","texte":"since"},{"id":"g1","texte":"for"},{"id":"g2","texte":"ago"},{"id":"g3","texte":"during"}],"droite":[{"id":"d0","texte":"il y a"},{"id":"d1","texte":"depuis (point de départ)"},{"id":"d2","texte":"pendant (+ nom)"},{"id":"d3","texte":"pendant (durée)"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m8"]},"explication":"**since** introduit un point de départ (*since 2019*)."},{"cle":{"type":"zone","ids":["m23"]},"explication":"**ago** se place après la durée (*two years ago*) et appelle le prétérit."},{"cle":{"type":"association","paires":{"g2":"d0","g0":"d1","g3":"d2","g1":"d3"}},"explication":"**since** + point de départ, **for** + durée, **ago** après une durée, **during** + nom."}]$ex$::jsonb),
  ('04e22a95-7692-5dbd-8be7-4d2bb117d749'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"La vie d’Emma à Cork","competence":"se-reperer-temps","situation":"Nous sommes en 2025. Emma raconte son parcours à Cork, et le lycée rappelle des délais à respecter.","documents":[{"id":"frise","type":"frise","titre":"Emma’s timeline","debut":2015,"fin":2025,"pas":5,"evenements":[{"id":"z1","date":2017,"nom":"Moves to Cork"},{"id":"z2","date":2020,"nom":"Joins the choir"},{"id":"z3","date":2023,"nom":"Wins a prize"}],"source":"Frise inventée pour l’exercice"},{"id":"delais","type":"tableau","titre":"School deadlines","colonnes":["Task","Rule"],"lignes":[["Essay","Hand it in by Friday."],["Library book","You can keep it until Monday."],["Permission form","Return it within a week."]],"enteteLignes":true,"source":"Tableau écrit pour l’exercice"}],"questions":[{"enonce":"Il y a combien d’années qu’Emma a rejoint la chorale ? (Nous sommes en 2025.)","aide":"Soustrais la date de la frise à 2025.","type":"nombre","unite":"ans"},{"enonce":"Touche l’événement qui s’est passé « two years ago ».","aide":"Cherche la date 2025 − 2 ans.","type":"zone","document":"frise","multiple":false},{"enonce":"Complète la phrase sur Cork.","aide":"2017 est un point de départ.","type":"trous","segments":["Emma has lived in Cork ",0," 2017."],"banque":["since","ago","for","during"]},{"enonce":"Emma a encore son livre de bibliothèque dimanche. Que dit la règle ?","aide":"« Until » signifie jusqu’à.","type":"choix","options":[{"id":"a","texte":"Elle doit le rendre dimanche, la règle dit d’ici lundi"},{"id":"b","texte":"Elle peut le garder, la règle dit jusqu’à lundi"},{"id":"c","texte":"Elle doit le rendre dans l’heure, la règle dit within"},{"id":"d","texte":"Elle ne peut plus le garder, lundi est passé"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":5,"tolerance":0},"affichage":"5 ans","explication":"2025 − 2020 = **5 ans** : *five years ago*."},{"cle":{"type":"zone","ids":["z3"]},"explication":"**Wins a prize** : 2023, soit il y a deux ans."},{"cle":{"type":"trous","trous":[["since"]]},"affichage":"since","explication":"**since 2017** : point de départ, present perfect car elle y habite encore."},{"cle":{"type":"choix","ids":["b"]},"explication":"**until Monday** : elle peut le garder jusqu’à lundi. *By* signifierait « d’ici, au plus tard »."}]$ex$::jsonb),
  ('04e22a95-7692-5dbd-8be7-4d2bb117d749'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"La crue de Kingsford","competence":"analyser-document","situation":"Dans la ville imaginaire de Kingsford, la rivière est montée. Un article et un graphique relatent la semaine.","documents":[{"id":"article","type":"texte","genre":"article","titre":"Kingsford Herald","blocs":["The river rose during the night. While the villagers were sleeping, the water reached the bridge. The rain began on Monday and has not stopped since. The bridge will stay closed until Friday and the school will reopen within a week."],"source":"Article imaginé pour l’exercice"},{"id":"pluie","type":"graphique","forme":"barres","titre":"Rainfall each day","categories":["Mon","Tue","Wed","Thu"],"series":[{"nom":"Rain","valeurs":[12,28,35,20],"teinte":"bleu"}],"axeY":{"titre":"Rain","unite":"mm","min":0,"max":40,"pas":10},"valeurs":false,"source":"Chiffres inventés pour l’exercice"}],"questions":[{"enonce":"Touche la conjonction suivie d’un sujet et d’un verbe (et non d’un simple nom).","aide":"Elle est suivie de « the villagers were sleeping ».","type":"zone","document":"article","multiple":false},{"enonce":"Pourquoi ne peut-on pas écrire « during the villagers were sleeping » ?","aide":"Compare avec « during the night ».","type":"choix","options":[{"id":"a","texte":"During ne s’emploie que pour une durée en années"},{"id":"b","texte":"During est une conjonction : il demande un verbe"},{"id":"c","texte":"During ne s’emploie qu’avec le present perfect"},{"id":"d","texte":"During est une préposition : il demande un nom"}],"multiple":false},{"enonce":"Touche le jour où il a le plus plu.","aide":"Cherche la barre la plus haute.","type":"zone","document":"pluie","multiple":false},{"enonce":"Complète la phrase sur la pluie.","aide":"Monday est un point de départ.","type":"trous","segments":["The rain has not stopped ",0," Monday."],"banque":["since","for","ago","until"]},{"enonce":"Complète les prévisions.","aide":"Jusqu’à vendredi ; d’ici moins d’une semaine.","type":"trous","segments":["The bridge will stay closed ",0," Friday and the school will reopen ",1," a week."],"banque":["since","within","ago","until"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m6"]},"explication":"**While** est une conjonction : elle introduit une proposition complète."},{"cle":{"type":"choix","ids":["d"]},"explication":"**During** + nom (*during the night*) ; **while** + sujet et verbe."},{"cle":{"type":"zone","ids":["k2"]},"explication":"**Wednesday** : 35 mm, le maximum de la semaine."},{"cle":{"type":"trous","trous":[["since"]]},"affichage":"since","explication":"**since Monday** : point de départ, avec le present perfect."},{"cle":{"type":"trous","trous":[["until"],["within"]]},"affichage":"until · within","explication":"**until Friday** (jusqu’à) et **within a week** (d’ici moins d’une semaine)."}]$ex$::jsonb),
  ('f9338913-2163-558a-9b7e-dfcde601ce9e'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"La chambre de Lily","competence":"comprendre-langue","situation":"Lily habite à Londres et décrit son immeuble, sa chambre et son humeur. Repère les adjectifs.","documents":[{"id":"lily","type":"texte","genre":"article","titre":"Lily’s world","blocs":["Lily lives in a tall building in London.","Her room is small but bright. She has a red sofa and old books. Today she looks happy."],"source":"Texte écrit pour l’exercice"}],"questions":[{"enonce":"Touche tous les adjectifs du texte.","aide":"Un adjectif décrit un nom ou suit un verbe comme *is* ou *looks*.","type":"zone","document":"lily","multiple":true},{"enonce":"Relie chaque adjectif à son sens.","aide":"Pense à l’immeuble, à la chambre, aux livres et à l’humeur de Lily.","type":"association","gauche":[{"id":"g0","texte":"tall"},{"id":"g1","texte":"small"},{"id":"g2","texte":"old"},{"id":"g3","texte":"happy"}],"droite":[{"id":"d0","texte":"haut, grand"},{"id":"d1","texte":"vieux"},{"id":"d2","texte":"petit"},{"id":"d3","texte":"heureux"}]},{"enonce":"Le texte dit « old books ». Pourquoi pas « olds books » ?","aide":"Regarde comment s’écrit « tall » devant le pluriel dans d’autres phrases.","type":"choix","options":[{"id":"a","texte":"Un adjectif anglais ne prend jamais de -s"},{"id":"b","texte":"Parce que « books » est un nom indénombrable"},{"id":"c","texte":"Parce que « old » devrait être placé après le nom"},{"id":"d","texte":"Parce que le -s n’existe que devant une voyelle"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m4","m11","m13","m17","m20","m25"]},"explication":"Les six adjectifs sont **tall, small, bright, red, old, happy**."},{"cle":{"type":"association","paires":{"g0":"d0","g2":"d1","g1":"d2","g3":"d3"}},"explication":"**tall** = haut, **small** = petit, **old** = vieux, **happy** = heureux."},{"cle":{"type":"choix","ids":["a"]},"explication":"L’adjectif anglais est **invariable** : il ne s’accorde ni en genre ni en nombre."}]$ex$::jsonb),
  ('f9338913-2163-558a-9b7e-dfcde601ce9e'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Le stand de la brocante","competence":"manier-langue","situation":"Karim tient un stand à la brocante du village et décrit les objets en vente. Dans une annonce, les adjectifs se suivent dans un ordre précis.","documents":[{"id":"stand","type":"tableau","titre":"Stall list","colonnes":["Item","Opinion","Size","Age","Colour","Material"],"lignes":[["table","lovely","big","old","brown","wooden"],["bag","nice","small","new","black","leather"]],"enteteLignes":true,"source":"Tableau écrit pour l’exercice"},{"id":"film","type":"dialogue","modele":"sms","titre":"Messages","participants":[{"nom":"Mina","emoji":"👧","cote":"gauche"},{"nom":"Tim","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Mina","texte":"The film was boring. I was so bored!"},{"qui":"Tim","texte":"Really? I was excited. The trailer looked amazing!"}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche la case qui dit dans quelle matière est fait le sac.","aide":"Cherche la ligne « bag », colonne « Material ».","type":"zone","document":"stand","multiple":false},{"enonce":"Écris l’annonce de la table dans le bon ordre. Le premier mot est « a ».","aide":"Opinion, taille, âge, couleur, matière : les colonnes du tableau suivent déjà cet ordre.","type":"ordre","items":[{"id":"a","texte":"big"},{"id":"b","texte":"wooden"},{"id":"c","texte":"brown"},{"id":"d","texte":"a"},{"id":"e","texte":"old"},{"id":"f","texte":"table"},{"id":"g","texte":"lovely"}]},{"enonce":"Quelle annonce du sac est écrite dans le bon ordre ?","aide":"Relis les colonnes du tableau de gauche à droite.","type":"choix","options":[{"id":"a","texte":"a nice small new black leather bag"},{"id":"b","texte":"a leather nice small new black bag"},{"id":"c","texte":"a nice small black new leather bag"},{"id":"d","texte":"a small nice new black leather bag"}],"multiple":false},{"enonce":"Touche l’adjectif en -ING qui décrit ce qui provoque l’ennui, puis celui qui décrit ce qui provoque l’émerveillement.","aide":"Un adjectif en -ING décrit la chose qui provoque l’émotion.","type":"zone","document":"film","multiple":true}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r1c5"]},"explication":"Le sac est en **leather** (cuir) : la matière se lit en dernière colonne."},{"cle":{"type":"ordre","ids":["d","g","a","e","c","b","f"]},"explication":"**a lovely big old brown wooden table** : opinion → taille → âge → couleur → matière → nom."},{"cle":{"type":"choix","ids":["a"]},"explication":"**a nice small new black leather bag** : opinion, taille, âge, couleur, matière."},{"cle":{"type":"zone","ids":["m3","m15"]},"explication":"**boring** (le film est ennuyeux) et **amazing** (la bande-annonce est impressionnante) décrivent ce qui provoque l’émotion ; *bored* et *excited* disent ce que les personnes ressentent."}]$ex$::jsonb),
  ('f9338913-2163-558a-9b7e-dfcde601ce9e'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Ceux qui fréquentent la bibliothèque de Millbrook","competence":"analyser-document","situation":"Dans la petite ville imaginaire de Millbrook, la bibliothèque a compté ses visiteurs en une semaine. Lis l’article et le graphique.","documents":[{"id":"article","type":"texte","genre":"article","titre":"Millbrook Library","blocs":["In the small town of Millbrook, the poor are not invisible. The unemployed meet every Tuesday at the library.","The British visitors say they love the quiet rooms, and the young are getting busier every month."],"source":"Article imaginé pour l’exercice"},{"id":"visites","type":"graphique","forme":"barres-h","titre":"Visitors in one week","categories":["The young","The unemployed","The retired"],"series":[{"nom":"Visitors","valeurs":[65,40,25],"teinte":"turquoise"}],"axeY":{"titre":"Visitors","min":0,"max":80,"pas":10},"valeurs":false,"source":"Chiffres inventés pour l’exercice"}],"questions":[{"enonce":"Touche les adjectifs employés comme noms pour désigner un groupe de personnes (the poor, the unemployed…).","aide":"Ils sont précédés de *the* et le verbe qui les suit est au pluriel.","type":"zone","document":"article","multiple":true},{"enonce":"Touche la barre du groupe le plus nombreux.","aide":"Compare la longueur des trois barres.","type":"zone","document":"visites","multiple":false},{"enonce":"Combien de visiteurs en tout cette semaine-là ?","aide":"Additionne les trois groupes.","type":"nombre"},{"enonce":"Complète avec le bon verbe.","aide":"*The retired* désigne plusieurs personnes.","type":"trous","segments":["The retired ",0," the smallest group."],"banque":["be","is","are","am"]},{"enonce":"Relie chaque groupe à sa traduction.","aide":"Dans chaque cas, *the* + adjectif désigne tout un groupe.","type":"association","gauche":[{"id":"g0","texte":"the poor"},{"id":"g1","texte":"the unemployed"},{"id":"g2","texte":"the British"},{"id":"g3","texte":"the rich"}],"droite":[{"id":"d0","texte":"les riches"},{"id":"d1","texte":"les Britanniques"},{"id":"d2","texte":"les chômeurs"},{"id":"d3","texte":"les pauvres"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m7","m12","m20","m30"]},"explication":"**poor, unemployed, British, young** désignent des groupes entiers : *the* + adjectif, verbe au pluriel."},{"cle":{"type":"zone","ids":["k0"]},"explication":"**The young** ont la barre la plus longue : 65 visiteurs."},{"cle":{"type":"nombre","valeur":130,"tolerance":0},"affichage":"130","explication":"65 + 40 + 25 = **130 visiteurs**."},{"cle":{"type":"trous","trous":[["are"]]},"affichage":"are","explication":"**The retired are** : un adjectif substantivé désigne un groupe, donc le verbe est au pluriel."},{"cle":{"type":"association","paires":{"g3":"d0","g2":"d1","g1":"d2","g0":"d3"}},"explication":"**the poor** = les pauvres, **the unemployed** = les chômeurs, **the British** = les Britanniques, **the rich** = les riches."}]$ex$::jsonb),
  ('098b4f81-9a0a-53cd-b573-1bf57d4eeead'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"La sortie annulée de M. Dale","competence":"comprendre-langue","situation":"La classe de M. Dale devait visiter un château, mais la sortie est annulée. Repère comment l’article dit la cause et le but.","documents":[{"id":"article","type":"texte","genre":"article","titre":"School trip cancelled","blocs":["The school trip was cancelled because of the storm. Mr Dale called the bus company to ask for a refund. Everybody was sad because they wanted to see the castle."],"source":"Article imaginé pour l’exercice"}],"questions":[{"enonce":"Touche les deux mots « because » qui annoncent une cause.","aide":"Il y en a un devant « of the storm » et un devant « they wanted ».","type":"zone","document":"article","multiple":true},{"enonce":"Complète la phrase.","aide":"Après le blanc, il y a un groupe nominal.","type":"trous","segments":["The trip was cancelled ",0," the storm."],"banque":["to","because","so that","because of"]},{"enonce":"Complète le but de l’appel de M. Dale.","aide":"Le but est suivi d’un verbe à la base.","type":"trous","segments":["Mr Dale called the bus company ",0," ask for a refund."],"banque":["for","to","because","so"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m5","m23"]},"explication":"Les deux **because** introduisent une cause : *because of* + nom, *because* + proposition."},{"cle":{"type":"trous","trous":[["because of"]]},"affichage":"because of","explication":"**because of** + nom (*the storm*) ; *because* demande un sujet et un verbe."},{"cle":{"type":"trous","trous":[["to"]]},"affichage":"to","explication":"**to** + base verbale exprime le but (*to ask*)."}]$ex$::jsonb),
  ('098b4f81-9a0a-53cd-b573-1bf57d4eeead'::uuid, 2, 2, 10, 35, 5,
   $ex${"titre":"Le gâteau d’anniversaire de la sœur de Nina","competence":"analyser-document","situation":"Nina et Omar préparent l’anniversaire de la sœur de Nina. Leur échange dit pourquoi et dans quel but ils agissent ; un tableau résume les causes de ce qui s’est passé.","documents":[{"id":"sms","type":"dialogue","modele":"sms","titre":"Messages","participants":[{"nom":"Nina","emoji":"👧","cote":"gauche"},{"nom":"Omar","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Nina","texte":"I’m going shopping to buy some flowers."},{"qui":"Omar","texte":"Why flowers?"},{"qui":"Nina","texte":"They’re for my sister. It’s her birthday."},{"qui":"Omar","texte":"I’ll bake a cake so that everyone can eat it tonight."},{"qui":"Nina","texte":"Perfect! Let’s leave early so as not to be late."}],"source":"Messages écrits pour l’exercice"},{"id":"causes","type":"tableau","titre":"What happened and why","colonnes":["Event","Cause"],"lignes":[["The party was moved indoors","the rain"],["The cake was a success","Omar’s recipe"]],"enteteLignes":true,"source":"Tableau écrit pour l’exercice"}],"questions":[{"enonce":"Touche le mot qui annonce le destinataire des fleurs (suivi d’un nom).","aide":"Après lui, il y a « my sister », pas un verbe.","type":"zone","document":"sms","multiple":false},{"enonce":"Complète la phrase d’Omar.","aide":"Le sujet de la proposition de but est différent (everyone).","type":"trous","segments":["Omar will bake a cake ",0," everyone can eat it tonight."],"banque":["in order","for","so that","to"]},{"enonce":"Remets en ordre la phrase de Nina. Le premier mot est « so ».","aide":"Au négatif, on ne dit pas « to not ».","type":"ordre","items":[{"id":"a","texte":"not"},{"id":"b","texte":"late"},{"id":"c","texte":"to"},{"id":"d","texte":"as"},{"id":"e","texte":"so"},{"id":"f","texte":"be"}]},{"enonce":"Complète la ligne du tableau.","aide":"La pluie est une cause négative et un nom.","type":"trous","segments":["The party was moved indoors ",0," the rain."],"banque":["so as","because of","thanks to","because"]},{"enonce":"Relie chaque expression à ce qui la suit.","aide":"Pense aux exemples de l’échange.","type":"association","gauche":[{"id":"g0","texte":"because"},{"id":"g1","texte":"because of"},{"id":"g2","texte":"to"},{"id":"g3","texte":"so that"}],"droite":[{"id":"d0","texte":"une proposition, sujet différent"},{"id":"d1","texte":"un groupe nominal"},{"id":"d2","texte":"une proposition (sujet + verbe)"},{"id":"d3","texte":"un verbe à la base"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m10"]},"explication":"**for** + nom : il désigne le destinataire (*for my sister*)."},{"cle":{"type":"trous","trous":[["so that"]]},"affichage":"so that","explication":"**so that** + proposition avec un sujet différent et un modal (*can*)."},{"cle":{"type":"ordre","ids":["e","d","a","c","f","b"]},"explication":"**so as not to be late** : la négation se place avant *to*."},{"cle":{"type":"trous","trous":[["because of"]]},"affichage":"because of","explication":"**because of** + nom ; *thanks to* serait réservé à une cause positive."},{"cle":{"type":"association","paires":{"g3":"d0","g1":"d1","g0":"d2","g2":"d3"}},"explication":"**because** + proposition ; **because of** + nom ; **to** + verbe ; **so that** + proposition à sujet différent."}]$ex$::jsonb),
  ('098b4f81-9a0a-53cd-b573-1bf57d4eeead'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Les vols annulés de Cardiff","competence":"analyser-document","situation":"Une tempête touche l’aéroport de Cardiff. Le tableau des départs et un article racontent comment les voyageurs ont été pris en charge.","documents":[{"id":"depart","type":"fiche","modele":"horaires","entete":"Cardiff Airport","sousTitre":"Departures","emoji":"✈️","lignes":[{"texte":"Dublin 9.20","valeur":"Cancelled: storm","id":"z1"},{"texte":"Paris 10.05","valeur":"Delayed: technical check","id":"z2"},{"texte":"Rome 11.30","valeur":"On time","id":"z3"}],"source":"Tableau imaginé pour l’exercice"},{"id":"article","type":"texte","genre":"article","titre":"Airport news","blocs":["The airline told passengers to wait so that it could find hotels. Volunteers brought blankets to keep the travellers warm. Thanks to the volunteers, hundreds of people slept safely in the terminal."],"source":"Article imaginé pour l’exercice"}],"questions":[{"enonce":"Touche la ligne du vol annulé à cause de la tempête.","aide":"Cherche la cause écrite à droite.","type":"zone","document":"depart","multiple":false},{"enonce":"Quelle phrase sur le vol de Paris est correcte ?","aide":"Après « because of », un groupe nominal ; après « because », une proposition.","type":"choix","options":[{"id":"a","texte":"The Paris flight was delayed because of a technical check."},{"id":"b","texte":"The Paris flight was delayed because of a technical check was needed."},{"id":"c","texte":"The Paris flight was delayed because a technical check."},{"id":"d","texte":"The Paris flight was delayed so that a technical check."}],"multiple":false},{"enonce":"Complète la phrase de l’article.","aide":"La compagnie a un sujet différent de celui de « wait ».","type":"trous","segments":["The airline told passengers to wait ",0," it could find hotels."],"banque":["because of","in order to","so that","for"]},{"enonce":"Complète la phrase sur les couvertures.","aide":"Un verbe à la base suit le blanc.","type":"trous","segments":["Volunteers brought blankets ",0," keep the travellers warm."],"banque":["for","to","so that","because"]},{"enonce":"Touche le mot qui annonce une cause positive, un bienfait.","aide":"Il est suivi de « to the volunteers ».","type":"zone","document":"article","multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z1"]},"explication":"Le vol pour **Dublin** est annulé : « Cancelled: storm »."},{"cle":{"type":"choix","ids":["a"]},"explication":"**because of** + nom (*a technical check*) ; jamais *because of* + sujet et verbe."},{"cle":{"type":"trous","trous":[["so that"]]},"affichage":"so that","explication":"**so that** + proposition avec un modal (*could*) : le sujet du but (*it*) diffère de celui de *told*."},{"cle":{"type":"trous","trous":[["to"]]},"affichage":"to","explication":"**to** + base verbale exprime le but."},{"cle":{"type":"zone","ids":["m20"]},"explication":"**Thanks** (to) introduit une cause positive : *thanks to the volunteers*."}]$ex$::jsonb),
  ('b92b0ef4-e23b-59e9-9d00-ba6dfb90d75e'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Ne lâche rien, Jules !","competence":"comprendre-langue","situation":"Jules s’entraîne pour une course avec son coach. Les verbes qu’ils emploient changent de sens selon la particule.","documents":[{"id":"course","type":"dialogue","modele":"sms","titre":"Messages","participants":[{"nom":"Coach","emoji":"🏃","cote":"gauche"},{"nom":"Jules","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Coach","texte":"Don’t give up, Jules! You’re almost there."},{"qui":"Jules","texte":"I’m looking for my bottle. Could you look after my bag?"},{"qui":"Coach","texte":"Sure. Turn on the music and keep going!"}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche les deux mots du verbe à particule qui veut dire « abandonner ».","aide":"Le coach l’emploie pour encourager Jules.","type":"zone","document":"course","multiple":true},{"enonce":"Relie chaque verbe à son sens.","aide":"Retrouve chaque verbe dans la conversation.","type":"association","gauche":[{"id":"g0","texte":"give up"},{"id":"g1","texte":"look for"},{"id":"g2","texte":"look after"},{"id":"g3","texte":"turn on"}],"droite":[{"id":"d0","texte":"abandonner"},{"id":"d1","texte":"chercher"},{"id":"d2","texte":"allumer"},{"id":"d3","texte":"garder, s’occuper de"}]},{"enonce":"Comment dit-on « Allume-la ! » à propos de la musique ?","aide":"Dans un verbe à particule, le pronom s’intercale.","type":"choix","options":[{"id":"a","texte":"Turn on it!"},{"id":"b","texte":"It turn on!"},{"id":"c","texte":"Turn it on!"},{"id":"d","texte":"On it turn!"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m1","m2"]},"explication":"**give up** signifie « abandonner » : le sens n’a rien à voir avec « donner en haut »."},{"cle":{"type":"association","paires":{"g0":"d0","g1":"d1","g3":"d2","g2":"d3"}},"explication":"**give up** = abandonner, **look for** = chercher, **look after** = s’occuper de, **turn on** = allumer."},{"cle":{"type":"choix","ids":["c"]},"explication":"**Turn it on!** : le pronom se place entre le verbe et la particule."}]$ex$::jsonb),
  ('b92b0ef4-e23b-59e9-9d00-ba6dfb90d75e'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Le bureau des objets trouvés","competence":"manier-langue","situation":"Hugo travaille au bureau des objets trouvés de sa gare. Il a affiché le sens des verbes qu’il emploie toute la journée.","documents":[{"id":"verbes","type":"tableau","titre":"Verbs of the day","colonnes":["Verb","Meaning"],"lignes":[["look for","chercher"],["look after","s’occuper de"],["look into","enquêter sur"],["look up","chercher dans un dictionnaire"],["put off","reporter"],["give up","abandonner"]],"enteteLignes":true,"source":"Tableau écrit pour l’exercice"}],"questions":[{"enonce":"Range chaque verbe du tableau.","aide":"Avec un verbe à particule, on dit *look it up* ; avec un verbe prépositionnel, on dit *look after it*.","type":"categories","categories":[{"id":"c0","texte":"verbe prépositionnel (pronom après)"},{"id":"c1","texte":"verbe à particule (pronom au milieu)"}],"items":[{"id":"i0","texte":"give up"},{"id":"i1","texte":"look for"},{"id":"i2","texte":"look after"},{"id":"i3","texte":"look into"},{"id":"i4","texte":"put off"},{"id":"i5","texte":"look up"}]},{"enonce":"Touche la case qui dit ce que signifie « look into ».","aide":"Cherche la ligne « look into ».","type":"zone","document":"verbes","multiple":false},{"enonce":"Complète avec la bonne préposition.","aide":"Il s’agit de garder le chat pendant une absence.","type":"trous","segments":["Could you look ",0," my cat while I’m away?"],"banque":["at","after","for","into"]},{"enonce":"Remets les mots dans l’ordre. Le premier mot est « Who ».","aide":"La préposition peut rester à la fin de la phrase.","type":"ordre","items":[{"id":"a","texte":"waiting"},{"id":"b","texte":"Who"},{"id":"c","texte":"you"},{"id":"d","texte":"for"},{"id":"e","texte":"are"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"categories","items":{"i0":"c1","i1":"c0","i2":"c0","i3":"c0","i4":"c1","i5":"c1"}},"explication":"**look after, look into, look for** : la préposition reste collée au complément (*look after him*) ; **look up, put off, give up** : le pronom s’intercale (*look it up*)."},{"cle":{"type":"zone","ids":["r2c1"]},"explication":"**look into** = enquêter sur (la police look into a robbery)."},{"cle":{"type":"trous","trous":[["after"]]},"affichage":"after","explication":"**look after** = s’occuper de."},{"cle":{"type":"ordre","ids":["b","e","c","a","d"]},"explication":"**Who are you waiting for?** : en anglais courant, la préposition reste en fin de phrase."}]$ex$::jsonb),
  ('b92b0ef4-e23b-59e9-9d00-ba6dfb90d75e'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Le voyage reporté","competence":"analyser-document","situation":"Sam et Eli préparent un voyage en train. Lis le courriel de Sam et regarde les horaires.","documents":[{"id":"mail","type":"texte","genre":"lettre","titre":"Hi Eli","blocs":["We had to put the trip off until Sunday. I look forward to seeing you then.","Could you look up the train times? Which train are you waiting for?"],"source":"Courriel écrit pour l’exercice"},{"id":"trains","type":"tableau","titre":"Train times","colonnes":["Train","Leaves","Arrives"],"lignes":[["A","09:15","11:40"],["B","10:05","12:30"]],"enteteLignes":true,"source":"Horaires inventés pour l’exercice"}],"questions":[{"enonce":"Combien de minutes dure le trajet du train A ?","aide":"Passe de 09:15 à 11:40 : compte d’abord les heures, puis les minutes.","type":"nombre","unite":"minutes"},{"enonce":"Touche la préposition laissée à la fin de la question.","aide":"Le verbe est *wait* ; la préposition qui le suit est restée tout à la fin.","type":"zone","document":"mail","multiple":false},{"enonce":"Quelle phrase est correcte ?","aide":"Pour un verbe à particule, le pronom s’intercale.","type":"choix","options":[{"id":"a","texte":"Let’s put it off"},{"id":"b","texte":"Let’s put off it"},{"id":"c","texte":"Let’s put on off it"},{"id":"d","texte":"Let’s off put it"}],"multiple":false},{"enonce":"Pourquoi Sam écrit-il « I look forward to seeing you » et non « to see » ?","aide":"Remplace « seeing you » par « the weekend » : « to » reste-t-il le même ?","type":"choix","options":[{"id":"a","texte":"« to » est ici une préposition : il faut un gérondif après"},{"id":"b","texte":"Parce qu’il y a déjà un infinitif dans la phrase"},{"id":"c","texte":"Parce que « look forward » ne se construit jamais avec un verbe"},{"id":"d","texte":"Parce que « seeing » est un adjectif"}],"multiple":false},{"enonce":"Relie chaque verbe à son sens.","aide":"Tous les verbes commencent par *look*, c’est la suite qui change le sens.","type":"association","gauche":[{"id":"g0","texte":"look into"},{"id":"g1","texte":"look up"},{"id":"g2","texte":"look after"},{"id":"g3","texte":"look forward to"}],"droite":[{"id":"d0","texte":"chercher dans une liste"},{"id":"d1","texte":"s’occuper de"},{"id":"d2","texte":"attendre avec impatience"},{"id":"d3","texte":"enquêter sur"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":145,"tolerance":0},"affichage":"145 minutes","explication":"De 09:15 à 11:40 : 2 h 25, soit 120 + 25 = **145 minutes**."},{"cle":{"type":"zone","ids":["m28"]},"explication":"**for** : en anglais courant, la préposition d’un verbe prépositionnel reste en fin de phrase."},{"cle":{"type":"choix","ids":["a"]},"explication":"**Let’s put it off** : le pronom se place entre le verbe et la particule."},{"cle":{"type":"choix","ids":["a"]},"explication":"Dans **look forward to**, *to* est une préposition : le verbe qui suit prend la forme en -ING."},{"cle":{"type":"association","paires":{"g1":"d0","g2":"d1","g3":"d2","g0":"d3"}},"explication":"**look into** = enquêter, **look up** = chercher dans une liste ou un dictionnaire, **look after** = s’occuper de, **look forward to** = attendre avec impatience."}]$ex$::jsonb),
  ('c8dc4e39-37ed-53de-9059-73b4ccfdf7b6'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Mia veut rendre visite à son cousin","competence":"comprendre-langue","situation":"Mia échange avec Sam au sujet de son cousin qui habite à Leeds. Repère comment se construisent leurs questions.","documents":[{"id":"sms","type":"dialogue","modele":"sms","titre":"Messages","participants":[{"nom":"Mia","emoji":"👧","cote":"gauche"},{"nom":"Sam","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Mia","texte":"Where does your cousin live?"},{"qui":"Sam","texte":"In Leeds. Can you come this weekend?"},{"qui":"Mia","texte":"Maybe. How long does the train take?"}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche les trois auxiliaires placés devant le sujet dans les questions.","aide":"Ils précèdent « your cousin », « you » et « the train ».","type":"zone","document":"sms","multiple":true},{"enonce":"Remets la première question en ordre. Le premier mot est « Where ».","aide":"Mot interrogatif, auxiliaire, sujet, verbe à la base.","type":"ordre","items":[{"id":"a","texte":"cousin"},{"id":"b","texte":"Where"},{"id":"c","texte":"does"},{"id":"d","texte":"your"},{"id":"e","texte":"live"}]},{"enonce":"Complète la question sur la durée du trajet.","aide":"Mia veut savoir combien de temps dure le trajet.","type":"trous","segments":["How ",0," does the train take?"],"banque":["often","far","long","many"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m1","m7","m15"]},"explication":"Les auxiliaires sont **does, Can, does** : l’auxiliaire passe devant le sujet et le verbe reste à la base."},{"cle":{"type":"ordre","ids":["b","c","d","a","e"]},"explication":"**Where does your cousin live?** : mot interrogatif + auxiliaire + sujet + verbe."},{"cle":{"type":"trous","trous":[["long"]]},"affichage":"long","explication":"**How long** interroge sur la durée."}]$ex$::jsonb),
  ('c8dc4e39-37ed-53de-9059-73b4ccfdf7b6'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"La carte postale d’Ivy depuis Bath","competence":"analyser-document","situation":"Ivy écrit à sa grand-mère. Pour chaque phrase de la carte, il existe une question qui la fait répondre.","documents":[{"id":"carte","type":"fiche","modele":"carte-postale","entete":"Greetings from Bath","sousTitre":"Dear Gran","emoji":"🏞️","lignes":[{"texte":"The school is two kilometres from my house.","id":"z1"},{"texte":"I cycle there every morning.","id":"z2"},{"texte":"We have been in Bath for a week.","id":"z3"},{"texte":"I have two cousins here.","id":"z4"},{"texte":"Mrs Hill, our neighbour, lives next door.","id":"z5"}],"pied":"Love, Ivy","source":"Carte écrite pour l’exercice"}],"questions":[{"enonce":"Touche la phrase qui répond à « How often does Ivy cycle to school? ».","aide":"« How often » demande la fréquence.","type":"zone","document":"carte","multiple":false},{"enonce":"Quelle question a pour réponse « Two kilometres » ?","aide":"On parle d’une distance.","type":"choix","options":[{"id":"a","texte":"How often is the school from Ivy’s house?"},{"id":"b","texte":"How long is the school from Ivy’s house?"},{"id":"c","texte":"How many is the school from Ivy’s house?"},{"id":"d","texte":"How far is the school from Ivy’s house?"}],"multiple":false},{"enonce":"Complète la question sur les cousins.","aide":"Les cousins se comptent.","type":"trous","segments":["How ",0," cousins does Ivy have?"],"banque":["many","often","much","long"]},{"enonce":"Quelle question a pour réponse « Mrs Hill » ?","aide":"Le mot interrogatif est le sujet : pas d’auxiliaire.","type":"choix","options":[{"id":"a","texte":"Who does live next door?"},{"id":"b","texte":"Whom lives next door?"},{"id":"c","texte":"Who does next door live?"},{"id":"d","texte":"Who lives next door?"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z2"]},"explication":"**I cycle there every morning** : « every morning » donne la fréquence."},{"cle":{"type":"choix","ids":["d"]},"explication":"**How far** interroge sur la distance."},{"cle":{"type":"trous","trous":[["many"]]},"affichage":"many","explication":"**How many** + nom pluriel dénombrable (*cousins*)."},{"cle":{"type":"choix","ids":["d"]},"explication":"**Who lives next door?** : quand *who* est le sujet, on n’ajoute pas *do*."}]$ex$::jsonb),
  ('c8dc4e39-37ed-53de-9059-73b4ccfdf7b6'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Le nouveau professeur et la vitre brisée","competence":"manier-langue","situation":"Cara et Dev parlent du nouveau professeur, M. Wells. Un article de l’école raconte aussi une vitre brisée.","documents":[{"id":"sms","type":"dialogue","modele":"sms","titre":"Messages","participants":[{"nom":"Cara","emoji":"👧","cote":"gauche"},{"nom":"Dev","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Cara","texte":"How is Mr Wells today? He was ill."},{"qui":"Dev","texte":"He’s better. He teaches us every Monday, doesn’t he?"},{"qui":"Cara","texte":"Yes. What is he like?"},{"qui":"Dev","texte":"Very patient and funny. He can’t sing, though."}],"source":"Messages écrits pour l’exercice"},{"id":"article","type":"texte","genre":"article","titre":"School news","blocs":["A window was broken at school on Friday. Mr Wells found the pieces and talked to the pupils. The caretaker saw a ball in the corridor. Nobody knows who broke it."],"source":"Article imaginé pour l’exercice"}],"questions":[{"enonce":"Touche le mot qui montre que Cara demande le caractère de M. Wells (et non sa santé).","aide":"On ne demande pas « comment va-t-il ? ».","type":"zone","document":"sms","multiple":false},{"enonce":"Complète le tag de Dev.","aide":"Phrase affirmative : tag négatif, avec l’auxiliaire do.","type":"trous","segments":["He teaches us every Monday, ",0," he?"],"banque":["does","hasn’t","doesn’t","isn’t"]},{"enonce":"Complète le tag.","aide":"Phrase négative : tag positif.","type":"trous","segments":["He can’t sing, ",0," he?"],"banque":["doesn’t","can","can’t","does"]},{"enonce":"Range chaque question selon la place du mot interrogatif.","aide":"Demande-toi si le mot interrogatif fait l’action ou la subit.","type":"categories","categories":[{"id":"c0","texte":"Sujet : pas d’auxiliaire"},{"id":"c1","texte":"Complément : auxiliaire obligatoire"}],"items":[{"id":"i0","texte":"What did the caretaker see?"},{"id":"i1","texte":"Who broke the window?"},{"id":"i2","texte":"Who did Mr Wells talk to?"},{"id":"i3","texte":"Which ball hit the glass?"},{"id":"i4","texte":"Who found the pieces?"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m21"]},"explication":"**What is he like?** demande comment il est (caractère), alors que *How is he?* demande comment il va."},{"cle":{"type":"trous","trous":[["doesn t"]]},"affichage":"doesn’t","explication":"**doesn’t he?** : polarité inversée, et *do* car il n’y a pas d’auxiliaire."},{"cle":{"type":"trous","trous":[["can"]]},"affichage":"can","explication":"**can he?** : phrase négative, tag positif avec le même auxiliaire."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c0","i2":"c1","i3":"c0","i4":"c0"}},"explication":"Quand le mot interrogatif **est le sujet** (*who found*), pas de *did*. Quand il est **complément** (*what did the caretaker see*), l’auxiliaire est obligatoire."}]$ex$::jsonb),
  ('d3c8789b-1699-5096-8f18-b5f850c1c5cf'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"La routine de Sara","competence":"comprendre-langue","situation":"Sara décrit sa routine dans un petit portrait pour le journal du lycée. Observe où se placent les adverbes.","documents":[{"id":"sara","type":"texte","genre":"article","titre":"Sara’s routine","blocs":["Sara often works late. She is always happy and she never skips breakfast.","She speaks English fluently."],"source":"Texte écrit pour l’exercice"}],"questions":[{"enonce":"Touche les trois adverbes de fréquence.","aide":"Ils répondent à la question « combien de fois ? ».","type":"zone","document":"sara","multiple":true},{"enonce":"Remets les mots dans l’ordre. Le premier mot est « Sara ».","aide":"L’adverbe de fréquence se place avant le verbe lexical.","type":"ordre","items":[{"id":"a","texte":"often"},{"id":"b","texte":"Sara"},{"id":"c","texte":"late"},{"id":"d","texte":"works"}]},{"enonce":"Où se place l’adverbe de manière « fluently » dans la dernière phrase ?","aide":"Relis la dernière phrase du texte.","type":"choix","options":[{"id":"a","texte":"Avant le verbe, juste après le sujet du verbe"},{"id":"b","texte":"Tout au début, avant le sujet de la phrase"},{"id":"c","texte":"Entre le verbe et son complément d’objet"},{"id":"d","texte":"Après le complément : She speaks English fluently"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m1","m6","m10"]},"explication":"**often, always, never** sont des adverbes de fréquence."},{"cle":{"type":"ordre","ids":["b","a","d","c"]},"explication":"**Sara often works late.** : *often* se place avant le verbe lexical."},{"cle":{"type":"choix","ids":["d"]},"explication":"L’adverbe de manière se place **après le verbe ou après son complément**, jamais entre le verbe et son COD."}]$ex$::jsonb),
  ('d3c8789b-1699-5096-8f18-b5f850c1c5cf'::uuid, 2, 2, 10, 35, 5,
   $ex${"titre":"Un appel difficile","competence":"manier-langue","situation":"Jo et Eli se parlent au téléphone. Plusieurs adverbes en -ly ou sans -ly ont un sens qui surprend.","documents":[{"id":"appel","type":"dialogue","modele":"sms","titre":"Messages","participants":[{"nom":"Jo","emoji":"👧","cote":"gauche"},{"nom":"Eli","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Jo","texte":"Sorry, I could hardly hear you."},{"qui":"Eli","texte":"I’m terribly sorry! I was speaking quietly because the baby is asleep."},{"qui":"Jo","texte":"No problem. I haven’t seen Tom lately. Is he OK?"},{"qui":"Eli","texte":"He is, but he drives too fast and his car is nearly dead."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche l’adverbe qui veut dire « à peine ».","aide":"Ne pense pas à « durement ».","type":"zone","document":"appel","multiple":false},{"enonce":"Relie chaque adverbe à son sens.","aide":"Trois de ces adverbes sont des faux amis.","type":"association","gauche":[{"id":"g0","texte":"hardly"},{"id":"g1","texte":"lately"},{"id":"g2","texte":"nearly"},{"id":"g3","texte":"terribly"}],"droite":[{"id":"d0","texte":"terriblement"},{"id":"d1","texte":"presque"},{"id":"d2","texte":"récemment"},{"id":"d3","texte":"à peine"}]},{"enonce":"Touche l’adverbe qui a la même forme que l’adjectif.","aide":"Il n’a pas de -ly.","type":"zone","document":"appel","multiple":false},{"enonce":"Complète avec l’adverbe formé sur l’adjectif quiet.","aide":"Pour un verbe, il faut un adverbe.","type":"trous","segments":["Eli was speaking ",0,"."],"banque":["quieter","quietly","quiet","quite"]},{"enonce":"Quelle phrase est correcte ?","aide":"N’insère jamais l’adverbe entre le verbe et son COD.","type":"choix","options":[{"id":"a","texte":"She speaks fluently English"},{"id":"b","texte":"She speaks English very fluent"},{"id":"c","texte":"Fluently she English speaks"},{"id":"d","texte":"She speaks English fluently"}],"multiple":false}]}$ex$::jsonb,
