   $ex$[{"cle":{"type":"zone","ids":["r1c1"]},"explication":"Le vélo de route coûte **£450** : c’est le plus cher."},{"cle":{"type":"trous","trous":[["more"]]},"affichage":"more","explication":"**more expensive than** : adjectif de plus de deux syllabes."},{"cle":{"type":"choix","ids":["d"]},"explication":"**the lightest** : superlatif d’un adjectif court, toujours avec *the*."},{"cle":{"type":"trous","trous":[["light"]]},"affichage":"light","explication":"**not as light as** : l’adjectif reste à la forme de base entre les deux *as*."},{"cle":{"type":"association","paires":{"g2":"d0","g0":"d1","g3":"d2","g1":"d3"}},"explication":"**better**, **worse** (irréguliers), **heavier** (-y devient -ier), **more expensive** (adjectif long)."}]$ex$::jsonb),
  ('ef18c6ba-e202-5378-a388-f9e4a5869aec'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Chaque jour plus froid","competence":"analyser-document","situation":"Leo et Mia suivent la météo d’une semaine d’hiver. La courbe donne la température à 6 heures du matin.","documents":[{"id":"courbe","type":"graphique","forme":"courbe","titre":"Temperature at 6 a.m.","categories":["Mon","Tue","Wed","Thu","Fri"],"series":[{"nom":"Temperature","valeurs":[11,8,6,2,4],"teinte":"bleu"}],"axeY":{"titre":"Temperature","unite":"°C","min":0,"max":12,"pas":2},"source":"Valeurs inventées pour l’exercice"},{"id":"sms","type":"dialogue","modele":"sms","titre":"Messages","participants":[{"nom":"Leo","emoji":"👦","cote":"gauche"},{"nom":"Mia","emoji":"👧","cote":"droite"}],"repliques":[{"qui":"Leo","texte":"Tuesday was colder than Monday."},{"qui":"Mia","texte":"And Thursday was the coldest day of the week!"},{"qui":"Leo","texte":"It’s getting colder and colder."},{"qui":"Mia","texte":"The colder it gets, the more hot chocolate I drink."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Mia dit que c’était le jour le plus froid : touche le point de la courbe qui le confirme.","aide":"Cherche la température la plus basse.","type":"zone","document":"courbe","multiple":false},{"enonce":"Combien de degrés de moins le jeudi que le lundi ?","aide":"Lis les deux températures sur la courbe.","type":"nombre","unite":"°C"},{"enonce":"Compare vendredi (4 °C) et jeudi (2 °C).","aide":"Vendredi est un peu moins froid que jeudi.","type":"trous","segments":["Friday was ",0," as cold as Thursday."],"banque":["not","very","more","much"]},{"enonce":"Quelle phrase sur mercredi (6 °C) est correcte ?","aide":"Place 6 entre les valeurs de mardi et de jeudi.","type":"choix","options":[{"id":"a","texte":"Wednesday was colder than Tuesday but warmer than Thursday."},{"id":"b","texte":"Wednesday was colder than Thursday but warmer than Tuesday."},{"id":"c","texte":"Wednesday was the coldest day of the week."},{"id":"d","texte":"Wednesday was as cold as Monday this week."}],"multiple":false},{"enonce":"Complète la phrase de Mia.","aide":"Structure de proportion : the + comparatif, the + comparatif.","type":"trous","segments":["The colder it gets, the ",0," hot chocolate Mia drinks."],"banque":["much","many","most","more"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["k3"]},"explication":"**Thursday** : 2 °C, la valeur la plus basse."},{"cle":{"type":"nombre","valeur":9,"tolerance":0},"affichage":"9 °C","explication":"11 − 2 = **9 °C** de moins le jeudi."},{"cle":{"type":"trous","trous":[["not"]]},"affichage":"not","explication":"**not as cold as** : le vendredi est moins froid que le jeudi."},{"cle":{"type":"choix","ids":["a"]},"explication":"8 > 6 > 2 : mercredi est **plus froid que mardi** mais **plus chaud que jeudi**."},{"cle":{"type":"trous","trous":[["more"]]},"affichage":"more","explication":"**the more** : *the colder it gets, the more I drink*."}]$ex$::jsonb),
  ('df1e1253-9ff3-56bc-9b67-44f2b8e16422'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Le vélo et le parapluie de Mia","competence":"manier-langue","situation":"Mia raconte sa journée de samedi dans un petit journal de classe. Observe les petits mots devant les noms.","documents":[{"id":"journal","type":"texte","genre":"article","titre":"Mia’s Saturday","blocs":["Mia bought a bike and an umbrella on Saturday.","The bike is red. The umbrella is yellow."],"source":"Texte écrit pour l’exercice"}],"questions":[{"enonce":"Touche les articles qui présentent un objet pour la première fois.","aide":"Cherche les objets que Mia vient d’acheter : on ne les a pas encore mentionnés.","type":"zone","document":"journal","multiple":true},{"enonce":"Pourquoi écrit-on « The bike » dans le deuxième paragraphe ?","aide":"Compare avec la première phrase du texte.","type":"choix","options":[{"id":"a","texte":"Parce qu’il n’existe qu’un seul vélo dans le monde entier"},{"id":"b","texte":"Parce que « bike » commence par un son de consonne"},{"id":"c","texte":"Parce que le nom « bike » est ici employé au pluriel"},{"id":"d","texte":"Le vélo a déjà été cité : le lecteur sait de quel vélo on parle"}],"multiple":false},{"enonce":"Complète la première phrase du texte.","aide":"Prononce chaque mot : *bike* commence par un son de consonne, *umbrella* par un son de voyelle.","type":"trous","segments":["Mia bought ",0," bike and ",1," umbrella."],"banque":["an","some","the","a"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m2","m5"]},"explication":"Les deux premiers articles, **a** bike et **an** umbrella, présentent des objets nouveaux : on emploie *a / an* pour un singulier dénombrable non identifié."},{"cle":{"type":"choix","ids":["d"]},"explication":"Le vélo a été **déjà mentionné** : il est identifié, donc on emploie **the**."},{"cle":{"type":"trous","trous":[["a"],["an"]]},"affichage":"a · an","explication":"**a** bike (son de consonne) et **an** umbrella (son de voyelle) : c’est le son qui décide."}]$ex$::jsonb),
  ('df1e1253-9ff3-56bc-9b67-44f2b8e16422'::uuid, 2, 2, 10, 35, 3,
   $ex${"titre":"Un SMS dans le train","competence":"manier-langue","situation":"Ana et Leo s’écrivent pendant que Leo voyage. Regarde quels noms n’ont aucun article, puis range les articles dans les bonnes cases.","documents":[{"id":"sms","type":"dialogue","modele":"sms","titre":"Messages","participants":[{"nom":"Ana","emoji":"👧","cote":"gauche"},{"nom":"Leo","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Ana","texte":"Hi Leo! Are you on the 9.15 train?"},{"qui":"Leo","texte":"Yes! I’m reading books and drinking coffee. Life is easy on a train!"},{"qui":"Ana","texte":"Lucky you. I hate noise, and my seat is next to a baby."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche les noms employés au sens général, sans article.","aide":"Ces noms ne sont ni précédés de a / an ni de the : on parle de la chose en général.","type":"zone","document":"sms","multiple":true},{"enonce":"Range chaque phrase selon le mot qui manque dans le blanc.","aide":"Prononce le mot suivant : le son décide entre a et an. Un superlatif ou un objet unique appelle the.","type":"categories","categories":[{"id":"c0","texte":"a"},{"id":"c1","texte":"an"},{"id":"c2","texte":"the"},{"id":"c3","texte":"rien (Ø)"}],"items":[{"id":"i0","texte":"___ dogs are loyal."},{"id":"i1","texte":"She is ___ best player."},{"id":"i2","texte":"I need ___ umbrella."},{"id":"i3","texte":"___ life is hard."},{"id":"i4","texte":"We waited ___ hour."},{"id":"i5","texte":"He is ___ European."},{"id":"i6","texte":"___ Moon is bright tonight."}]},{"enonce":"Ana écrit « my seat is next to a baby ». Pourquoi « a » et non « the » ?","aide":"Ana n’a pas encore parlé de ce bébé avant cette phrase.","type":"choix","options":[{"id":"a","texte":"Parce que « baby » est un nom indénombrable"},{"id":"b","texte":"Parce qu’un superlatif suit toujours « a »"},{"id":"c","texte":"Ce bébé n’a pas encore été présenté au lecteur"},{"id":"d","texte":"Parce qu’il n’y a qu’un seul bébé au monde"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m12","m15","m16","m26"]},"explication":"**books, coffee, Life, noise** : pluriel ou indénombrable pris au sens général, on n’écrit rien (l’article zéro)."},{"cle":{"type":"categories","items":{"i0":"c3","i1":"c2","i2":"c1","i3":"c3","i4":"c1","i5":"c0","i6":"c2"}},"explication":"**an** devant un son de voyelle (*umbrella*, *hour* : le h est muet) ; **a** devant *European* (son « you ») ; **the** devant l’objet unique (*Moon*) et le superlatif ; **rien** pour *life* et *dogs* pris au sens général."},{"cle":{"type":"choix","ids":["c"]},"explication":"C’est un bébé **non identifié** : on le présente avec **a** (singulier dénombrable, première mention)."}]$ex$::jsonb),
  ('df1e1253-9ff3-56bc-9b67-44f2b8e16422'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Le mail plein de fautes","competence":"analyser-document","situation":"Sam écrit de Londres à son ami Tom, mais son mail contient des erreurs de déterminants. Corrige-le en t’aidant du tableau de la famille d’accueil.","documents":[{"id":"mail","type":"texte","genre":"lettre","titre":"Hi Tom!","blocs":["I’m writing from London. The life here is great! I live with an English family.","I have an university lesson every day, and I wait for a hour at the station when the train is late.","I walk along the Thames and I always say that the money is not everything."],"source":"Courriel écrit pour l’exercice"},{"id":"famille","type":"tableau","titre":"The host family","colonnes":["Possesseur","Objet possédé"],"lignes":[["Peter (un seul garçon)","car"],["les élèves (students)","bags"],["les enfants (children)","toys"],["Marie","brother"]],"enteteLignes":true,"source":"Tableau écrit pour l’exercice"}],"questions":[{"enonce":"Touche les quatre articles fautifs du courriel.","aide":"Deux sont des articles de sens général qu’il faut supprimer, deux ne respectent pas la règle du son.","type":"zone","document":"mail","multiple":true},{"enonce":"Corrige les deux articles qui suivent la règle du son.","aide":"Prononce *university* (« you-ni… ») et *hour* (« aoueur »).","type":"trous","segments":["I have ",0," university lesson and I wait for ",1," hour."],"banque":["some","an","the","a"]},{"enonce":"Comment corriger « The life here is great » ?","aide":"Sam parle de la vie en général, pas d’une vie précise.","type":"choix","options":[{"id":"a","texte":"A life here is great"},{"id":"b","texte":"Life here is great"},{"id":"c","texte":"The lives here are great"},{"id":"d","texte":"Lifes here are great"}],"multiple":false},{"enonce":"Relie chaque possesseur du tableau à la bonne forme.","aide":"Un pluriel en -s prend l’apostrophe seule ; un pluriel irrégulier prend ’s ; pour un possessif, le possesseur commande.","type":"association","gauche":[{"id":"g0","texte":"Peter"},{"id":"g1","texte":"les élèves"},{"id":"g2","texte":"les enfants"},{"id":"g3","texte":"Marie"}],"droite":[{"id":"d0","texte":"her brother"},{"id":"d1","texte":"the children’s toys"},{"id":"d2","texte":"Peter’s car"},{"id":"d3","texte":"the students’ bags"}]},{"enonce":"Remets les mots dans l’ordre pour dire « Les sacs des élèves sont ici ». Le premier mot est « The ».","aide":"Le possesseur passe devant l’objet possédé.","type":"ordre","items":[{"id":"a","texte":"are"},{"id":"b","texte":"students’"},{"id":"c","texte":"The"},{"id":"d","texte":"bags"},{"id":"e","texte":"here"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m4","m17","m26","m46"]},"explication":"**The** life et **the** money : sens général, on n’écrit rien ; **an** university : on dit « you », donc *a* ; **a** hour : le h est muet, donc *an*."},{"cle":{"type":"trous","trous":[["a"],["an"]]},"affichage":"a · an","explication":"**a** university (son de consonne « you ») et **an** hour (h muet, son de voyelle)."},{"cle":{"type":"choix","ids":["b"]},"explication":"**Life here is great** : un indénombrable pris au sens général ne prend aucun article."},{"cle":{"type":"association","paires":{"g3":"d0","g2":"d1","g0":"d2","g1":"d3"}},"explication":"**Peter’s car** (singulier : ’s), **the students’ bags** (pluriel en -s : apostrophe seule), **the children’s toys** (pluriel irrégulier : ’s), **her brother** (c’est Marie, la possesseuse)."},{"cle":{"type":"ordre","ids":["c","b","d","a","e"]},"explication":"**The students’ bags are here.** Le génitif se lit à l’envers du français : *students’* avant *bags*."}]$ex$::jsonb),
  ('8d44a97f-eb6d-5b16-a3ec-65b1bfbb6577'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Les règles du camp Willow","competence":"comprendre-langue","situation":"Lena est en colonie de vacances au camp Willow. L’affiche du camp explique ce que le directeur, Mr Hill, impose, permet ou organise.","documents":[{"id":"regles","type":"fiche","modele":"affiche","entete":"Summer camp rules","sousTitre":"Camp Willow — week 1","emoji":"⛺","lignes":[{"texte":"Mr Hill makes us clean the kitchen.","id":"z1"},{"texte":"Mr Hill lets us choose the evening game.","id":"z2"},{"texte":"Mr Hill gets the cook to prepare our snacks.","id":"z3"}],"pied":"Have fun!","source":"Affiche écrite pour l’exercice"}],"questions":[{"enonce":"Touche la ligne où les enfants sont obligés : ils n’ont pas le choix.","aide":"Quel verbe exprime la contrainte ?","type":"zone","document":"regles","multiple":false},{"enonce":"Touche la ligne où les enfants ont la permission de décider.","aide":"Quel verbe exprime la permission ?","type":"zone","document":"regles","multiple":false},{"enonce":"Complète avec le petit mot qui manque.","aide":"Un seul des quatre verbes (*make, have, get, let*) prend un petit mot devant la base verbale.","type":"trous","segments":["Lena got her brother ",0," help her with the tent."],"banque":["with","to","at","for"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z1"]},"explication":"**Mr Hill makes us clean the kitchen** : *make* exprime la contrainte, suivi du complément et de la base verbale."},{"cle":{"type":"zone","ids":["z2"]},"explication":"**Mr Hill lets us choose the evening game** : *let* exprime la permission, suivi de la base verbale."},{"cle":{"type":"trous","trous":[["to"]]},"affichage":"to","explication":"**to** : *get* est le seul des quatre verbes à se construire avec *to* (*I got him to help me*)."}]$ex$::jsonb),
  ('8d44a97f-eb6d-5b16-a3ec-65b1bfbb6577'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"La facture du garage Riverside","competence":"manier-langue","situation":"Carla n’a rien réparé elle-même : elle a confié sa voiture au garage Riverside. Sa facture le montre ligne par ligne.","documents":[{"id":"facture","type":"fiche","modele":"ticket","entete":"Riverside Garage","sousTitre":"Invoice — Carla Dunn","emoji":"🔧","lignes":[{"texte":"Brakes checked","valeur":"£40","id":"z1"},{"texte":"Oil changed","valeur":"£35","id":"z2"},{"texte":"Windscreen repaired","valeur":"£90","id":"z3"},{"separateur":true},{"texte":"TOTAL","valeur":"£165","gras":true,"id":"z4"}],"pied":"Thank you!","source":"Facture écrite pour l’exercice"}],"questions":[{"enonce":"Touche la ligne qui correspond à la phrase « Carla had her oil changed ».","aide":"Cherche le service qui parle de l’huile (*oil*).","type":"zone","document":"facture","multiple":false},{"enonce":"Écris la phrase : « Carla a fait vérifier ses freins. » Le premier mot est « Carla ».","aide":"Structure : *have* + objet + participe passé.","type":"ordre","items":[{"id":"a","texte":"her"},{"id":"b","texte":"had"},{"id":"c","texte":"brakes"},{"id":"d","texte":"Carla"},{"id":"e","texte":"checked"}]},{"enonce":"Que signifie « Carla had her windscreen repaired » ?","aide":"Qui a fait le travail, d’après la facture ?","type":"choix","options":[{"id":"a","texte":"Carla a promis de réparer son pare-brise bientôt"},{"id":"b","texte":"Carla ne répare jamais son pare-brise"},{"id":"c","texte":"Carla a réparé son pare-brise elle-même, au garage"},{"id":"d","texte":"Carla a fait réparer son pare-brise par le garage"}],"multiple":false},{"enonce":"Qui fait l’action ? Range chaque phrase.","aide":"Cherche la structure *have / get* + objet + participe passé : l’action est confiée à un tiers.","type":"categories","categories":[{"id":"c0","texte":"Je le fais moi-même"},{"id":"c1","texte":"Quelqu’un le fait pour moi"}],"items":[{"id":"i0","texte":"I had my hair cut."},{"id":"i1","texte":"I cut my hair."},{"id":"i2","texte":"He repaired his bike."},{"id":"i3","texte":"She got her car repaired."}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z2"]},"explication":"**Oil changed** : *Carla had her oil changed* veut dire qu’elle a fait changer son huile par le garage."},{"cle":{"type":"ordre","ids":["d","b","a","c","e"]},"explication":"**Carla had her brakes checked** : *have* + objet + participe passé, pour faire faire une chose par un tiers."},{"cle":{"type":"choix","ids":["d"]},"explication":"**Carla a fait réparer son pare-brise par le garage** : *have* + objet + participe passé, l’exécutant n’est pas Carla."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c0","i2":"c0","i3":"c1"}},"explication":"*I cut my hair* : moi ; *I had my hair cut* et *She got her car repaired* : un professionnel ; *He repaired his bike* : lui."}]$ex$::jsonb),
  ('8d44a97f-eb6d-5b16-a3ec-65b1bfbb6577'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Le voyage scolaire de Zoe au pays de Galles","competence":"manier-langue","situation":"Zoe revient d’un voyage scolaire au pays de Galles. Elle raconte à son ami Jack ce que leur professeur, Mr Fox, leur a imposé, permis ou fait organiser.","documents":[{"id":"mail","type":"texte","genre":"lettre","titre":"Zoe’s email","blocs":["Hi Jack,","The school trip to Wales was great but tough! Mr Fox made us walk ten kilometres on the first day, and he let us rest only at lunch. I got my sister to lend me her camera, so I have loads of photos. When I get home, I’ll have them printed at the shop.","See you on Monday! Zoe"],"source":"Courriel écrit pour l’exercice"},{"id":"sms","type":"dialogue","modele":"sms","titre":"Messages","participants":[{"nom":"Jack","emoji":"👦","cote":"gauche"},{"nom":"Zoe","emoji":"👧","cote":"droite"}],"repliques":[{"qui":"Jack","texte":"Did Mr Fox let you use your phone?"},{"qui":"Zoe","texte":"No! They were all kept in a box."},{"qui":"Jack","texte":"Poor you! Who took the group photo?"},{"qui":"Zoe","texte":"Mr Fox had the hostel manager take it."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche le verbe qui montre que Mr Fox a imposé la longue marche : les élèves n’avaient pas le choix.","aide":"Quel verbe exprime la contrainte ?","type":"zone","document":"mail","multiple":false},{"enonce":"Au passif, « Mr Fox let us rest » devient…","aide":"Au passif, *let* est remplacé par un autre verbe de permission, suivi de *to*.","type":"choix","options":[{"id":"a","texte":"We were let rest."},{"id":"b","texte":"We were allowed to rest."},{"id":"c","texte":"We were made to rest."},{"id":"d","texte":"We were let to rest."}],"multiple":false},{"enonce":"Touche le verbe qui suit « had the hostel manager » : sans *to*, avec la base verbale.","aide":"Avec *have*, on ne met pas *to* devant le verbe.","type":"zone","document":"sms","multiple":false},{"enonce":"Complète d’après le courriel de Zoe.","aide":"*Have* + objet + participe passé : l’action est faite par quelqu’un d’autre.","type":"trous","segments":["Zoe will have her photos ",0," at the shop."],"banque":["prints","print","printed","printing"]},{"enonce":"Relie chaque verbe à son sens.","aide":"Pense à la contrainte, à la permission, à la persuasion et au service rendu par un métier.","type":"association","gauche":[{"id":"g0","texte":"make"},{"id":"g1","texte":"let"},{"id":"g2","texte":"get"},{"id":"g3","texte":"have"}],"droite":[{"id":"d0","texte":"obliger"},{"id":"d1","texte":"faire faire par un professionnel"},{"id":"d2","texte":"persuader, obtenir de"},{"id":"d3","texte":"permettre"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m13"]},"explication":"**made** : *make* exprime la contrainte (*Mr Fox made us walk*), suivi du complément et de la base verbale."},{"cle":{"type":"choix","ids":["b"]},"explication":"**We were allowed to rest.** : au passif, on remplace *let* par *allow*."},{"cle":{"type":"zone","ids":["m29"]},"explication":"**take** : *have* + complément + base verbale, sans *to* (*Mr Fox had the manager take the photo*)."},{"cle":{"type":"trous","trous":[["printed"]]},"affichage":"printed","explication":"**printed** : *have* + objet + participe passé, le magasin imprimera les photos."},{"cle":{"type":"association","paires":{"g0":"d0","g3":"d1","g2":"d2","g1":"d3"}},"explication":"*Make* : obliger ; *let* : permettre ; *get* : persuader ; *have* : faire faire par quelqu’un dont c’est le rôle."}]$ex$::jsonb),
  ('d6b9f124-dfcd-519b-a367-23cd9d6f82b9'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Froid, faim et grand-père de 90 ans","competence":"manier-langue","situation":"La famille de Mia rentre d’une longue promenade. Le papa raconte l’état de chacun. En français, on dit « avoir » ; en anglais, ce n’est pas le même verbe.","documents":[{"id":"famille","type":"dialogue","modele":"sms","titre":"Messages","participants":[{"nom":"Dad","emoji":"👨","cote":"gauche"},{"nom":"Mia","emoji":"👧","cote":"droite"}],"repliques":[{"qui":"Dad","texte":"Quick, go inside! Mia is cold, Tom is hungry and Grandpa is ninety today!"},{"qui":"Mia","texte":"Don’t worry, Dad. I’ll make tea."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche les trois mots que le français exprimerait avec le verbe « avoir » (avoir froid, avoir faim, avoir 90 ans).","aide":"Cherche les mots qui décrivent l’état ou l’âge d’une personne.","type":"zone","document":"famille","multiple":true},{"enonce":"Complète la phrase de Dad.","aide":"Quel verbe sert à dire l’état en anglais ?","type":"trous","segments":["Tom ",0," hungry."],"banque":["does","is","have","has"]},{"enonce":"Comment dit-on « Grand-père a 90 ans » ?","aide":"Pour l’âge, l’anglais emploie *be* et ne dit pas « years ».","type":"choix","options":[{"id":"a","texte":"Grandpa has 90 years"},{"id":"b","texte":"Grandpa is 90"},{"id":"c","texte":"Grandpa does 90"},{"id":"d","texte":"Grandpa have 90 ans"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m5","m8","m12"]},"explication":"**cold, hungry, ninety** : l’anglais dit *be cold*, *be hungry*, *be ninety*, là où le français dit « avoir »."},{"cle":{"type":"trous","trous":[["is"]]},"affichage":"is","explication":"On emploie **is** : *Tom is hungry* (« Tom a faim »)."},{"cle":{"type":"choix","ids":["b"]},"explication":"**Grandpa is 90** : l’âge se dit avec *be*, jamais avec *have*."}]$ex$::jsonb),
  ('d6b9f124-dfcd-519b-a367-23cd9d6f82b9'::uuid, 2, 2, 10, 35, 5,
   $ex${"titre":"Le déjeuner de Max","competence":"comprendre-langue","situation":"Lena et Max discutent de leur matinée. Observe comment l’auxiliaire *do* travaille dans leur conversation.","documents":[{"id":"cafe","type":"dialogue","modele":"sms","titre":"Messages","participants":[{"nom":"Lena","emoji":"👩","cote":"gauche"},{"nom":"Max","emoji":"👨","cote":"droite"}],"repliques":[{"qui":"Lena","texte":"Did you have lunch at school, Max?"},{"qui":"Max","texte":"No, I didn’t. But I DO like a big dinner!"},{"qui":"Lena","texte":"So do I!"}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche les deux auxiliaires qui construisent la question et la négation au prétérit.","aide":"Le prétérit de *do* sert à poser une question et à nier.","type":"zone","document":"cafe","multiple":true},{"enonce":"Touche l’auxiliaire qui sert à insister (« si, j’aime vraiment »).","aide":"Il est écrit en majuscules dans la réponse de Max.","type":"zone","document":"cafe","multiple":false},{"enonce":"Dans « So do I », que fait Lena ?","aide":"Que dit-on quand on est d’accord avec quelqu’un ?","type":"choix","options":[{"id":"a","texte":"Elle nie ce que Max vient d’affirmer"},{"id":"b","texte":"Elle insiste sur le verbe de sa propre phrase"},{"id":"c","texte":"Elle reprend l’auxiliaire de Max pour dire « moi aussi »"},{"id":"d","texte":"Elle pose une question sur le dîner de Max"}],"multiple":false},{"enonce":"Complète la négation avec le verbe qui convient.","aide":"Après *didn’t*, le verbe reste à la base verbale.","type":"trous","segments":["I didn’t ",0," lunch at school."],"banque":["has","had","having","have"]},{"enonce":"Remets les mots dans l’ordre pour poser la question. Le premier mot est « Did ».","aide":"Auxiliaire, sujet, verbe : l’auxiliaire passe devant le sujet.","type":"ordre","items":[{"id":"a","texte":"Did"},{"id":"b","texte":"have"},{"id":"c","texte":"breakfast"},{"id":"d","texte":"today"},{"id":"e","texte":"you"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m0","m9"]},"explication":"**Did** (question) et **didn’t** (négation) : l’auxiliaire *do* porte la marque du temps et de la forme."},{"cle":{"type":"zone","ids":["m12"]},"explication":"**DO** à l’affirmative sert à insister ou à contredire : *I DO like a big dinner*."},{"cle":{"type":"choix","ids":["c"]},"explication":"**So do I** = « moi aussi » : l’anglais reprend l’auxiliaire de la phrase précédente."},{"cle":{"type":"trous","trous":[["have"]]},"affichage":"have","explication":"**I didn’t have lunch** : c’est *didn’t* qui porte le prétérit, donc *have* reste à la base."},{"cle":{"type":"ordre","ids":["a","e","b","c","d"]},"explication":"**Did you have breakfast today?** : auxiliaire, sujet, verbe à la base, complément."}]$ex$::jsonb),
  ('d6b9f124-dfcd-519b-a367-23cd9d6f82b9'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Le club de cuisine","competence":"analyser-texte","situation":"Le journal du lycée a publié les notes du club de cuisine. Lucie y cherche les auxiliaires. Aide-toi aussi du tableau des trois verbes.","documents":[{"id":"club","type":"texte","genre":"article","titre":"Cooking club notes","blocs":["Tom is cooking pasta. Lucy has a big pan.","She does her homework before the club, but she didn’t have breakfast. The pasta was cooked in ten minutes.","Have you finished? Does Lucy like pasta? Tom says: “I like pasta.”"],"source":"Texte écrit pour l’exercice"},{"id":"roles","type":"tableau","titre":"Three verbs, two jobs","colonnes":["Verbe","Comme auxiliaire","Comme verbe lexical"],"lignes":[["BE","forme en -ING, passif","être"],["HAVE","temps composés","avoir, posséder ; prendre (have breakfast)"],["DO","négation et question aux temps simples","faire"]],"enteteLignes":true,"source":"Tableau écrit pour l’exercice"}],"questions":[{"enonce":"Dans chaque phrase du texte, le verbe en gras est…","aide":"Un auxiliaire aide un autre verbe ; un verbe lexical porte le sens à lui seul.","type":"categories","categories":[{"id":"c0","texte":"auxiliaire"},{"id":"c1","texte":"verbe lexical"}],"items":[{"id":"i0","texte":"Tom **is** cooking pasta."},{"id":"i1","texte":"She **does** her homework."},{"id":"i2","texte":"The pasta **was** cooked in ten minutes."},{"id":"i3","texte":"Lucy **has** a big pan."},{"id":"i4","texte":"She **didn’t** have breakfast."},{"id":"i5","texte":"**Have** you finished?"}]},{"enonce":"Touche la case qui dit à quoi sert DO comme auxiliaire.","aide":"Cherche la ligne DO, colonne « Comme auxiliaire ».","type":"zone","document":"roles","multiple":false},{"enonce":"Pourquoi écrit-on « She didn’t have breakfast » et non « She hadn’t breakfast » ?","aide":"Regarde la ligne HAVE du tableau : que veut dire *have breakfast* ?","type":"choix","options":[{"id":"a","texte":"Parce que la forme « hadn’t » n’existe pas en anglais"},{"id":"b","texte":"Ici have est lexical (prendre) : la négation passe par do"},{"id":"c","texte":"Parce que « have » ne se met jamais au passé simple"},{"id":"d","texte":"Parce que « breakfast » est un nom indénombrable en anglais"}],"multiple":false},{"enonce":"Tom dit « I like pasta ». Lucy aussi aime les pâtes. Que répond-elle ?","aide":"Reprends l’auxiliaire de la phrase de Tom : il n’y en a pas, donc l’anglais en fabrique un.","type":"choix","options":[{"id":"a","texte":"So do I"},{"id":"b","texte":"So have I"},{"id":"c","texte":"So am I"},{"id":"d","texte":"So like I"}],"multiple":false},{"enonce":"Remets les mots dans l’ordre pour poser la question. Le premier mot est « Does ».","aide":"Auxiliaire, sujet, verbe lexical à la base, puis complément.","type":"ordre","items":[{"id":"a","texte":"Lucy"},{"id":"b","texte":"pan"},{"id":"c","texte":"a"},{"id":"d","texte":"Does"},{"id":"e","texte":"big"},{"id":"f","texte":"have"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"categories","items":{"i0":"c0","i1":"c1","i2":"c0","i3":"c1","i4":"c0","i5":"c0"}},"explication":"**is** cooking (forme en -ING), **didn’t**, **was** cooked (passif) et **Have** you finished (temps composé) sont des auxiliaires ; **has** (posséder) et **does** (faire) sont lexicaux."},{"cle":{"type":"zone","ids":["r2c1"]},"explication":"**DO** auxiliaire sert à la négation et à la question aux temps simples (*Does Lucy like pasta?*)."},{"cle":{"type":"choix","ids":["b"]},"explication":"*Have breakfast* = « prendre le petit-déjeuner » : **have** est lexical, donc la négation se fait avec **didn’t**."},{"cle":{"type":"choix","ids":["a"]},"explication":"**So do I** : *like* est lexical, on reprend avec l’auxiliaire fabriqué *do*."},{"cle":{"type":"ordre","ids":["d","a","f","c","e","b"]},"explication":"**Does Lucy have a big pan?** : *does* porte le -s de la 3e personne, donc *have* reste à la base."}]$ex$::jsonb),
  ('1dd18b35-d27e-51d4-94aa-35366acf5ed9'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Le frigo de Zoé","competence":"lire-tableau","situation":"Zoé prépare un gâteau pour l’anniversaire de sa sœur. Elle a noté ce qu’il y a dans le frigo. La recette demande 5 eggs.","documents":[{"id":"frigo","type":"tableau","titre":"What’s in the fridge?","colonnes":["Item","Quantity"],"lignes":[["eggs","12"],["milk","2 bottles"],["apples","6"],["rice","1 kg"],["tomatoes","5"],["bread","1 loaf"]],"enteteLignes":true,"source":"Tableau écrit pour l’exercice"}],"questions":[{"enonce":"Touche les trois aliments indénombrables (on ne peut pas dire « one milk, two milks »).","aide":"Un indénombrable se compte avec un intermédiaire : une bouteille, un kilo, une miche.","type":"zone","document":"frigo","multiple":true},{"enonce":"Complète avec many ou much.","aide":"*Milk* est indénombrable, *eggs* se compte.","type":"trous","segments":["How ",0," milk is there? And how ",1," eggs are there?"],"banque":["many","a little","a few","much"]},{"enonce":"La recette utilise 5 eggs. Combien d’eggs reste-t-il dans le frigo ?","aide":"Regarde la ligne « eggs » du tableau.","type":"nombre","unite":"eggs"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r1c0","r3c0","r5c0"]},"explication":"**milk, rice, bread** sont indénombrables : on les compte avec *a bottle of*, *a kilo of*, *a loaf of*."},{"cle":{"type":"trous","trous":[["much"],["many"]]},"affichage":"much · many","explication":"How **much** milk (indénombrable) et how **many** eggs (dénombrable pluriel)."},{"cle":{"type":"nombre","valeur":7,"tolerance":0},"affichage":"7 eggs","explication":"12 − 5 = **7 eggs**."}]$ex$::jsonb),
  ('1dd18b35-d27e-51d4-94aa-35366acf5ed9'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"L’affiche de la médiathèque","competence":"comprendre-langue","situation":"Jade lit l’affiche d’une médiathèque. Les petits mots de quantité y disent qui peut faire quoi, et ce qui manque.","documents":[{"id":"affiche","type":"fiche","modele":"affiche","entete":"Greenfield Library","sousTitre":"Welcome!","emoji":"📚","lignes":[{"texte":"Any student can join the library for free.","id":"z1"},{"texte":"You may borrow up to five books.","id":"z2"},{"texte":"Would you like some help? Ask our librarian.","id":"z3"},{"texte":"There aren’t any computers in the quiet room.","id":"z4"},{"texte":"Too many people? Come before 10 a.m.","id":"z5"}],"pied":"Open Monday to Saturday","teinte":"bleu","source":"Affiche écrite pour l’exercice"}],"questions":[{"enonce":"Touche la ligne qui fait une proposition d’aide.","aide":"Une offre ou une demande se construit avec *some*.","type":"zone","document":"affiche","multiple":false},{"enonce":"Touche la ligne qui dit que n’importe quel élève peut s’inscrire.","aide":"Le mot cherché signifie « n’importe lequel » dans une phrase affirmative.","type":"zone","document":"affiche","multiple":false},{"enonce":"Complète d’après l’affiche.","aide":"La phrase est négative.","type":"trous","segments":["There aren’t ",0," computers in the quiet room."],"banque":["any","much","some","a lot of"]},{"enonce":"Range chaque nom derrière le bon mot de quantité.","aide":"Peux-tu mettre un -s ou un chiffre devant ? Alors c’est dénombrable.","type":"categories","categories":[{"id":"c0","texte":"many"},{"id":"c1","texte":"much"}],"items":[{"id":"i0","texte":"books"},{"id":"i1","texte":"advice"},{"id":"i2","texte":"furniture"},{"id":"i3","texte":"homework"},{"id":"i4","texte":"students"},{"id":"i5","texte":"people"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z3"]},"explication":"La ligne **« Would you like some help? »** est une offre : on emploie *some* même dans une question."},{"cle":{"type":"zone","ids":["z1"]},"explication":"**Any student can join** : dans une phrase affirmative, *any* signifie « n’importe quel »."},{"cle":{"type":"trous","trous":[["any"]]},"affichage":"any","explication":"Dans une phrase négative, on emploie **any** : *There aren’t any computers*."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c1","i2":"c1","i3":"c1","i4":"c0","i5":"c0"}},"explication":"**many** devant les dénombrables pluriels (*people, books, students*) ; **much** devant les indénombrables (*homework, advice, furniture*)."}]$ex$::jsonb),
  ('1dd18b35-d27e-51d4-94aa-35366acf5ed9'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Le voyage scolaire à Édimbourg","competence":"analyser-document","situation":"Le professeur écrit aux parents avant le voyage à Édimbourg. Lis sa lettre et le tableau de l’organisation, puis réponds comme un organisateur.","documents":[{"id":"lettre","type":"texte","genre":"lettre","titre":"Dear parents","blocs":["Here is some information about our trip to Edinburgh. The news is good: the coach is free.","Please give your child one piece of advice: pack little luggage. Students must finish their homework before Friday."],"source":"Lettre écrite pour l’exercice"},{"id":"car","type":"tableau","titre":"The trip in numbers","colonnes":["Item","Number"],"lignes":[["Seats on the coach","50"],["Students","46"],["Teachers","3"],["Maximum pocket money (euros)","30"],["Mia’s pocket money (euros)","42"]],"enteteLignes":true,"source":"Chiffres inventés pour l’exercice"}],"questions":[{"enonce":"Touche les cinq noms indénombrables de la lettre.","aide":"Ils ne prennent jamais de -s et ne se placent pas derrière « a ».","type":"zone","document":"lettre","multiple":true},{"enonce":"Combien de places libres reste-t-il dans le car quand les élèves et les professeurs sont montés ?","aide":"Additionne d’abord les élèves et les professeurs.","type":"nombre","unite":"place"},{"enonce":"Complète avec le bon mot.","aide":"Le mot se place après l’adjectif.","type":"trous","segments":["The coach is big ",0," for 49 people."],"banque":["much","enough","many","too"]},{"enonce":"Mia a 42 euros, le maximum est 30. Quelle phrase est correcte ?","aide":"Compare 42 et 30, puis demande-toi si « money » est dénombrable.","type":"choix","options":[{"id":"a","texte":"She has enough pocket money"},{"id":"b","texte":"She has few pocket money"},{"id":"c","texte":"She has too many pocket money"},{"id":"d","texte":"She has too much pocket money"}],"multiple":false},{"enonce":"Remets les mots dans l’ordre. Le premier mot est « Please ».","aide":"Le verbe est suivi de la personne, puis de ce qu’on donne.","type":"ordre","items":[{"id":"a","texte":"some"},{"id":"b","texte":"advice"},{"id":"c","texte":"Please"},{"id":"d","texte":"me"},{"id":"e","texte":"give"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m3","m10","m24","m27","m32"]},"explication":"**information, news, advice, luggage, homework** : ce sont des indénombrables ; *news* est singulier malgré son -s."},{"cle":{"type":"nombre","valeur":1,"tolerance":0},"affichage":"1 place","explication":"46 + 3 = 49 personnes ; 50 − 49 = **1 place libre**."},{"cle":{"type":"trous","trous":[["enough"]]},"affichage":"enough","explication":"On dit **big enough** : *enough* se place après l’adjectif."},{"cle":{"type":"choix","ids":["d"]},"explication":"**too much** : *money* est indénombrable, et 42 dépasse 30."},{"cle":{"type":"ordre","ids":["c","e","d","a","b"]},"explication":"**Please give me some advice.** *Advice* est indénombrable : on utilise *some*, jamais « advices »."}]$ex$::jsonb),
  ('7d0c235b-59c9-5a4f-80ee-5d9cb00f403a'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Le vélo de Tom","competence":"comprendre-langue","situation":"Dans le journal d’une petite ville, un article raconte une histoire arrivée à Tom : son vélo a disparu, puis a été retrouvé. Repère les verbes au passif.","documents":[{"id":"article","type":"texte","genre":"article","titre":"Local news","blocs":["Last Friday, Tom’s bike was stolen outside the library. Nobody saw the thief.","Yesterday the bike was found in the river by a fisherman. The police returned it to Tom."],"source":"Article imaginé pour l’exercice"}],"questions":[{"enonce":"Touche tous les mots qui forment les deux verbes au passif.","aide":"Un passif = *be* conjugué + participe passé. Il y en a deux dans l’article.","type":"zone","document":"article","multiple":true},{"enonce":"Pourquoi l’article ne dit-il pas qui a volé le vélo ?","aide":"Relis la phrase qui suit : « Nobody saw the thief. »","type":"choix","options":[{"id":"a","texte":"Le verbe est au présent, pas au passé"},{"id":"b","texte":"On ne sait pas qui est le voleur"},{"id":"c","texte":"Le complément d’agent est toujours interdit"},{"id":"d","texte":"Le voleur est évident pour tout le monde"}],"multiple":false},{"enonce":"Complète le passif.","aide":"Après *was*, on met le participe passé.","type":"trous","segments":["The bike was ",0," in the river."],"banque":["finds","find","found","finding"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m4","m5","m16","m17"]},"explication":"**was stolen** et **was found** : *be* (ici au prétérit) + participe passé. *Saw* et *returned* sont des verbes actifs."},{"cle":{"type":"choix","ids":["b"]},"explication":"**On ne sait pas qui est le voleur** : on emploie le passif quand l’agent est inconnu."},{"cle":{"type":"trous","trous":[["found"]]},"affichage":"found","explication":"**found** : le passif se forme avec *be* + participe passé (*was found*)."}]$ex$::jsonb),
  ('7d0c235b-59c9-5a4f-80ee-5d9cb00f403a'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Les nouvelles du musée de Hartley","competence":"manier-langue","situation":"Le musée de Hartley publie un bulletin mensuel. Cette fois, il parle de ses horaires, d’un vol, de travaux et d’une enquête.","documents":[{"id":"bulletin","type":"texte","genre":"article","titre":"Hartley Museum News","blocs":["Hartley Museum is opened every day at nine. Last night, two paintings were stolen.","At the moment, the roof is being repaired, and the new hall will be opened in May. The police say that the case has been solved."],"source":"Bulletin imaginé pour l’exercice"}],"questions":[{"enonce":"Touche les trois mots qui forment le verbe au present perfect passif.","aide":"Le present perfect passif se forme avec *has / have* + *been* + participe passé.","type":"zone","document":"bulletin","multiple":true},{"enonce":"Relie chaque verbe passif au temps qu’il porte.","aide":"C’est *be* qui porte le temps : regarde sa forme (*is*, *were*, *is being*, *will be*, *has been*).","type":"association","gauche":[{"id":"g0","texte":"is opened every day"},{"id":"g1","texte":"were stolen"},{"id":"g2","texte":"is being repaired"},{"id":"g3","texte":"will be opened"},{"id":"g4","texte":"has been solved"}],"droite":[{"id":"d0","texte":"Présent simple"},{"id":"d1","texte":"Présent en -ING"},{"id":"d2","texte":"Prétérit"},{"id":"d3","texte":"Present perfect"},{"id":"d4","texte":"Futur"}]},{"enonce":"Écris la phrase au passif : « Le rapport a été publié. » Le premier mot est « The ».","aide":"Present perfect passif : *has* + *been* + participe passé.","type":"ordre","items":[{"id":"a","texte":"been"},{"id":"b","texte":"The"},{"id":"c","texte":"has"},{"id":"d","texte":"published"},{"id":"e","texte":"report"}]},{"enonce":"Cette nuit, on a volé deux tableaux. Quelle phrase le dit ?","aide":"Le vol est passé et daté (« cette nuit »), et *paintings* est au pluriel.","type":"choix","options":[{"id":"a","texte":"Two paintings have stolen."},{"id":"b","texte":"Two paintings was stolen."},{"id":"c","texte":"Two paintings were stolen."},{"id":"d","texte":"Two paintings are stolen."}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m37","m38","m39"]},"explication":"**has been solved** : *has* + *been* + participe passé, le present perfect passif."},{"cle":{"type":"association","paires":{"g0":"d0","g2":"d1","g1":"d2","g4":"d3","g3":"d4"}},"explication":"Le passif garde le même participe ; seul *be* change : *is* (présent), *were* (prétérit), *is being* (-ING), *will be* (futur), *has been* (present perfect)."},{"cle":{"type":"ordre","ids":["b","e","c","a","d"]},"explication":"**The report has been published** : *has been* + participe passé."},{"cle":{"type":"choix","ids":["c"]},"explication":"**Two paintings were stolen.** : *be* au prétérit pluriel (*were*) + participe passé."}]$ex$::jsonb),
  ('7d0c235b-59c9-5a4f-80ee-5d9cb00f403a'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Les prix de l’école d’Oakfield","competence":"analyser-document","situation":"À l’école d’Oakfield, trois élèves ont reçu un prix lors de la remise des récompenses. Un article parle aussi de l’ancienne bibliothèque de Millbrook, dont on raconte des choses.","documents":[{"id":"prix","type":"tableau","titre":"Prize-giving","colonnes":["Pupil","Prize","Given by"],"lignes":[["Ella","a book","Mr Reed"],["Sam","a medal","the head"],["Nina","a trophy","Ms Grey"]],"source":"Tableau écrit pour l’exercice"},{"id":"biblio","type":"texte","genre":"article","titre":"Millbrook Library","blocs":["The old library of Millbrook is said to have been built in 1850. It is believed that the building will be closed next year, but nobody knows for sure."],"source":"Article imaginé pour l’exercice"}],"questions":[{"enonce":"Touche la case qui dit qui a donné la médaille.","aide":"Cherche la ligne de la médaille, puis la colonne « Given by ».","type":"zone","document":"prix","multiple":false},{"enonce":"Complète d’après le tableau.","aide":"Après *was*, on met le participe passé.","type":"trous","segments":["Sam was ",0," a medal by the head."],"banque":["giving","given","gave","give"]},{"enonce":"Quelle phrase passive correspond à « Mr Reed gave Ella a book » ?","aide":"Le passif de *give* : *be* + participe passé, en commençant par la personne.","type":"choix","options":[{"id":"a","texte":"Ella was gave a book by Mr Reed."},{"id":"b","texte":"Ella given a book was by Mr Reed."},{"id":"c","texte":"Ella was given a book by Mr Reed."},{"id":"d","texte":"Ella gave a book by Mr Reed."}],"multiple":false},{"enonce":"Touche les deux participes passés des tournures impersonnelles (« on dit que », « on croit que »).","aide":"Ils suivent *is* et expriment ce que l’on raconte ou pense.","type":"zone","document":"biblio","multiple":true},{"enonce":"Relie chaque tournure à sa traduction.","aide":"*To have* + participe passé après *is said* renvoie au passé ; *to be* au présent.","type":"association","gauche":[{"id":"g0","texte":"It is said that…"},{"id":"g1","texte":"He is said to have left"},{"id":"g2","texte":"It is believed that…"},{"id":"g3","texte":"He is said to be…"}],"droite":[{"id":"d0","texte":"Il aurait quitté…"},{"id":"d1","texte":"On croit que…"},{"id":"d2","texte":"Il serait…"},{"id":"d3","texte":"On dit que…"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r1c2"]},"explication":"La médaille a été donnée par **the head** (colonne « Given by »)."},{"cle":{"type":"trous","trous":[["given"]]},"affichage":"given","explication":"**given** : *Sam was given a medal* — on commence par la personne."},{"cle":{"type":"choix","ids":["c"]},"explication":"**Ella was given a book by Mr Reed.** : le participe passé de *give* est *given*, et l’anglais commence volontiers par la personne."},{"cle":{"type":"zone","ids":["m6","m15"]},"explication":"**said** et **believed** : *is said to…* et *is believed that…* sont des tournures impersonnelles."},{"cle":{"type":"association","paires":{"g1":"d0","g2":"d1","g3":"d2","g0":"d3"}},"explication":"*It is said that…* : on dit que ; *is said to have left* : aurait quitté ; *is believed that…* : on croit que ; *is said to be…* : serait."}]$ex$::jsonb),
  ('a98e1c18-e208-5501-9bf6-a8e71311a2b4'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Les souvenirs de Gran","competence":"comprendre-langue","situation":"Ben envoie une photo de sa grand-mère au bord de la mer. Elle lui raconte comment elle vivait autrefois. Repère comment elle parle de ses anciennes habitudes.","documents":[{"id":"gran","type":"dialogue","modele":"sms","titre":"Messages","participants":[{"nom":"Ben","emoji":"👦","cote":"gauche"},{"nom":"Gran","emoji":"👵","cote":"droite"}],"repliques":[{"qui":"Ben","texte":"Gran, you look so relaxed in this photo!"},{"qui":"Gran","texte":"I used to live in a noisy flat. Now I live by the sea."},{"qui":"Gran","texte":"Every morning I would take the 7.15 train to work. Now I walk on the beach with my dog."},{"qui":"Ben","texte":"It sounds so different!"}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche les deux mots qui montrent que Gran ne vit plus dans un appartement bruyant.","aide":"Cherche la structure qui parle d’un état passé, aujourd’hui terminé.","type":"zone","document":"gran","multiple":true},{"enonce":"Touche le mot qui annonce une action répétée tous les matins dans le passé.","aide":"Il sert à raconter une habitude passée, surtout dans un récit.","type":"zone","document":"gran","multiple":false},{"enonce":"Complète la négation.","aide":"À la forme négative, avec *didn’t*, la structure perd son -d.","type":"trous","segments":["Gran didn’t ",0," live by the sea when she was young."],"banque":["use","uses","using","used"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m9","m10"]},"explication":"**used to** + base verbale exprime un état ou une habitude passés et révolus : Gran a vécu dans un appartement bruyant, mais ce n’est plus le cas."},{"cle":{"type":"zone","ids":["m25"]},"explication":"**would** + base verbale exprime une habitude passée répétée : chaque matin, Gran prenait le train."},{"cle":{"type":"trous","trous":[["use"]]},"affichage":"use","explication":"À la négation, on écrit **didn’t use to** : *didn’t* porte déjà le prétérit, donc *use* perd son -d."}]$ex$::jsonb),
  ('a98e1c18-e208-5501-9bf6-a8e71311a2b4'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Maya, hier et aujourd’hui","competence":"manier-langue","situation":"Maya a déménagé de Leeds à Bath. Sa vie a changé : son tableau compare les habitudes de ses dix ans et celles d’aujourd’hui.","documents":[{"id":"maya","type":"tableau","titre":"Maya’s life","colonnes":["","When Maya was ten","Today"],"lignes":[["Home","a flat in Leeds","a house in Bath"],["Saturday","play football","go swimming"],["School run","walk with her dad","take the bus"],["August","visit her gran by the sea","work in a café"]],"enteteLignes":true,"source":"Tableau écrit pour l’exercice"}],"questions":[{"enonce":"Touche la case qui dit comment Maya va à l’école aujourd’hui.","aide":"Cherche la ligne « School run » et la colonne « Today ».","type":"zone","document":"maya","multiple":false},{"enonce":"Écris une phrase sur le logement de Maya quand elle avait dix ans. Le premier mot est « Maya ».","aide":"Il s’agit d’un état passé révolu : la structure est *used to* + base verbale.","type":"ordre","items":[{"id":"a","texte":"Maya"},{"id":"b","texte":"a"},{"id":"c","texte":"to"},{"id":"d","texte":"live"},{"id":"e","texte":"flat"},{"id":"f","texte":"used"},{"id":"g","texte":"in"}]},{"enonce":"Quelle phrase NE PEUT PAS se dire avec « would » ?","aide":"*Would* accepte des actions répétées, pas des états. Quel verbe est un état ?","type":"choix","options":[{"id":"a","texte":"Maya would visit her gran every August."},{"id":"b","texte":"Maya would walk to school with her dad."},{"id":"c","texte":"Maya would live in a flat in Leeds."},{"id":"d","texte":"Maya would play football every Saturday."}],"multiple":false},{"enonce":"Relie chaque phrase à ce qu’elle exprime.","aide":"Repère le *be used to*, qui parle d’un état actuel, et le présent simple avec *usually*.","type":"association","gauche":[{"id":"g0","texte":"I used to live in Leeds."},{"id":"g1","texte":"I’m used to the rain."},{"id":"g2","texte":"We would visit Gran every August."},{"id":"g3","texte":"I usually walk to school."}],"droite":[{"id":"d0","texte":"Habitude présente"},{"id":"d1","texte":"J’y suis habitué"},{"id":"d2","texte":"Habitude passée répétée, dans un récit"},{"id":"d3","texte":"Autrefois oui, plus maintenant"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r2c2"]},"explication":"Aujourd’hui, Maya **takes the bus** : c’est une habitude présente, qui se dit au présent simple."},{"cle":{"type":"ordre","ids":["a","f","c","d","g","b","e"]},"explication":"**Maya used to live in a flat** : *used to* + base verbale pour un état passé qui n’existe plus."},{"cle":{"type":"choix","ids":["c"]},"explication":"**Maya would live in a flat** est impossible : *live* décrit ici un état, et *would* refuse les états. Pour un état passé, seul *used to* convient."},{"cle":{"type":"association","paires":{"g3":"d0","g1":"d1","g2":"d2","g0":"d3"}},"explication":"**used to** : révolu ; **be used to** : habitué ; **would** : habitude répétée du récit ; présent simple + *usually* : habitude présente."}]$ex$::jsonb),
  ('a98e1c18-e208-5501-9bf6-a8e71311a2b4'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Un nouveau départ à Glasgow","competence":"manier-langue","situation":"Sam vient de déménager de Cardiff à Glasgow pour un nouveau travail. Il écrit à son amie Aisha et a noté son emploi du temps avant et après.","documents":[{"id":"lettre","type":"texte","genre":"lettre","titre":"Sam’s email","blocs":["Dear Aisha,","Glasgow is great! In Cardiff I used to cycle to work, but here I take the underground. At first I wasn’t used to the crowds, but now I’m getting used to them. I’m also used to getting up early, because the office opens at seven. My neighbour says I’ll soon be used to living in the rain!","See you soon, Sam"],"source":"Courriel écrit pour l’exercice"},{"id":"emploi","type":"tableau","titre":"Sam’s routine","colonnes":["","Cardiff","Glasgow"],"lignes":[["Work","cycle","underground"],["Wake-up","7.30","6.00"],["Weather","dry","rainy"]],"enteteLignes":true,"source":"Tableau écrit pour l’exercice"}],"questions":[{"enonce":"Touche les deux verbes en -ING qui suivent « be used to ».","aide":"Dans *be used to*, *to* est une préposition : le verbe qui suit prend -ING.","type":"zone","document":"lettre","multiple":true},{"enonce":"D’après la lettre et le tableau, quelle phrase est exacte ?","aide":"Regarde la ligne « Work » : que faisait Sam à Cardiff, et que fait-il à Glasgow ?","type":"choix","options":[{"id":"a","texte":"Sam used to take the underground, but now he cycles."},{"id":"b","texte":"Sam is used to cycle to work, and he still does it."},{"id":"c","texte":"Sam used to cycle to work, but now he takes the underground."},{"id":"d","texte":"Sam is getting used to cycling to work in Glasgow."}],"multiple":false},{"enonce":"Complète d’après la ligne « Wake-up ».","aide":"*Be used to* est suivi d’un verbe en -ING.","type":"trous","segments":["Sam used to get up at 7.30. Now he’s used to ",0," up at six."],"banque":["get","gets","got","getting"]},{"enonce":"Range chaque phrase selon ce qu’elle exprime.","aide":"Cherche *used to* + base verbale, *be used to* + -ING, ou un simple présent avec *every day* / *often*.","type":"categories","categories":[{"id":"c0","texte":"Passé révolu (used to)"},{"id":"c1","texte":"Habitué (be used to + -ING)"},{"id":"c2","texte":"Habitude présente"}],"items":[{"id":"i0","texte":"I take the underground every day."},{"id":"i1","texte":"We often walk to the station."},{"id":"i2","texte":"I used to cycle to work."},{"id":"i3","texte":"I’m used to getting up at six."},{"id":"i4","texte":"He used to live in Cardiff."},{"id":"i5","texte":"She’s used to working late."}]},{"enonce":"Combien d’heures plus tôt Sam se lève-t-il à Glasgow qu’à Cardiff ?","aide":"Compare 7.30 et 6.00 : de 6.00 à 7.30, il y a une heure et demie.","type":"nombre","unite":"h"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m38","m55"]},"explication":"**getting** et **living** : après *be used to*, *used* est un adjectif et *to* une préposition, donc le verbe se met en -ING."},{"cle":{"type":"choix","ids":["c"]},"explication":"**Sam used to cycle to work, but now he takes the underground** : *used to* exprime une habitude passée terminée ; le tableau confirme le changement."},{"cle":{"type":"trous","trous":[["getting"]]},"affichage":"getting","explication":"**getting** : après *be used to*, on emploie le verbe en -ING (*he’s used to getting up*)."},{"cle":{"type":"categories","items":{"i0":"c2","i1":"c2","i2":"c0","i3":"c1","i4":"c0","i5":"c1"}},"explication":"*Used to* + base verbale : passé révolu ; *be used to* + -ING : habitué ; présent simple + adverbe : habitude présente."},{"cle":{"type":"nombre","valeur":1.5,"tolerance":0},"affichage":"1,5 h","explication":"De 6.00 à 7.30, il y a **1,5 h** (1 h 30)."}]$ex$::jsonb),
  ('36174924-a1c8-57f7-9f9d-0078c2351cc6'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Une lettre depuis la plage de Brighton","competence":"comprendre-langue","situation":"Dans sa lettre, Nell s’exclame à plusieurs reprises. Repère comment commencent ses exclamations.","documents":[{"id":"lettre","type":"texte","genre":"lettre","titre":"A letter from Brighton","blocs":["Dear Mum,","What a beautiful beach this is! What lovely weather! How warm the sea is!"],"source":"Lettre écrite pour l’exercice"}],"questions":[{"enonce":"Touche les trois mots qui ouvrent les exclamations de Nell.","aide":"Il n’y en a que deux différents : what et how.","type":"zone","document":"lettre","multiple":true},{"enonce":"Relie chaque exclamation à sa traduction.","aide":"What + nom, How + adjectif.","type":"association","gauche":[{"id":"g0","texte":"What a beautiful beach!"},{"id":"g1","texte":"What lovely weather!"},{"id":"g2","texte":"How warm the sea is!"}],"droite":[{"id":"d0","texte":"Quel beau temps !"},{"id":"d1","texte":"Que la mer est chaude !"},{"id":"d2","texte":"Quelle belle plage !"}]},{"enonce":"Complète l’exclamation sur le sable.","aide":"Après how, il faut un adjectif seul.","type":"trous","segments":["How ",0," the sand is!"],"banque":["soft","what","such","a soft"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m2","m8","m11"]},"explication":"Les exclamations commencent par **What, What, How**."},{"cle":{"type":"association","paires":{"g1":"d0","g2":"d1","g0":"d2"}},"explication":"**What** introduit un nom (*beach*, *weather*), **how** un adjectif (*warm*)."},{"cle":{"type":"trous","trous":[["soft"]]},"affichage":"soft","explication":"**How soft the sand is!** : *how* + adjectif, sujet et verbe dans l’ordre normal."}]$ex$::jsonb),
  ('36174924-a1c8-57f7-9f9d-0078c2351cc6'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Après le concert","competence":"manier-langue","situation":"Ana et Ben sortent d’un concert et s’écrivent des messages enthousiastes.","documents":[{"id":"sms","type":"dialogue","modele":"sms","titre":"Messages","participants":[{"nom":"Ana","emoji":"👧","cote":"gauche"},{"nom":"Ben","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Ana","texte":"What a concert!"},{"qui":"Ben","texte":"I know! It was such a great night."},{"qui":"Ana","texte":"And the singer! How beautifully she sang!"},{"qui":"Ben","texte":"It’s so sad that it’s over."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche les deux mots qui jouent le rôle de « what » et de « how » dans les messages de Ben.","aide":"Ben n’emploie ni what ni how : il a deux autres mots.","type":"zone","document":"sms","multiple":true},{"enonce":"Pourquoi Ana écrit-elle « How beautifully » et non « What beautifully » ?","aide":"Quelle est la nature du mot qui suit ?","type":"choix","options":[{"id":"a","texte":"Parce que how s’emploie après un nom propre"},{"id":"b","texte":"Parce que le verbe est au prétérit"},{"id":"c","texte":"Parce que beautifully est un nom pluriel"},{"id":"d","texte":"Parce que beautifully est un adverbe"}],"multiple":false},{"enonce":"Écris une exclamation dans le bon ordre. Le premier mot est « What ».","aide":"Ne fais pas d’inversion comme dans une question.","type":"ordre","items":[{"id":"a","texte":"mess"},{"id":"b","texte":"a"},{"id":"c","texte":"is"},{"id":"d","texte":"What"},{"id":"e","texte":"this"}]},{"enonce":"Complète la suite des messages de Ben.","aide":"Un nom (night) d’un côté, un adjectif (sad) de l’autre.","type":"trous","segments":["It was ",0," a great night and it’s ",1," sad it’s over."],"banque":["so","such","how","what"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m7","m19"]},"explication":"**such** fait comme *what* (devant un groupe nominal) et **so** comme *how* (devant un adjectif)."},{"cle":{"type":"choix","ids":["d"]},"explication":"**How** introduit un adjectif ou un adverbe ; **what** introduit un nom."},{"cle":{"type":"ordre","ids":["d","b","a","e","c"]},"explication":"**What a mess this is!** : sujet puis verbe, l’ordre normal."},{"cle":{"type":"trous","trous":[["such"],["so"]]},"affichage":"such · so","explication":"**such a great night** (groupe nominal) et **so sad** (adjectif)."}]$ex$::jsonb),
  ('36174924-a1c8-57f7-9f9d-0078c2351cc6'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"La kermesse, version Rita","competence":"analyser-document","situation":"Après la kermesse, plusieurs élèves ont écrit des exclamations, mais certaines contiennent une faute. Rita raconte aussi sa journée dans une lettre.","documents":[{"id":"liste","type":"tableau","titre":"Exclamations heard at the fair","colonnes":["Exclamation","Said by"],"lignes":[["What a mess this is!","Eli"],["What a mess is this!","Zack"],["How nice flowers!","Rita"],["What lovely flowers!","Max"],["It’s so cold!","Iris"]],"enteteLignes":true,"source":"Tableau écrit pour l’exercice"},{"id":"lettre","type":"texte","genre":"lettre","titre":"Rita’s letter","blocs":["Dear Aunt Jo,","What a day! The fair was such a success and the cakes were so delicious. How proudly Max sold them!"],"source":"Lettre écrite pour l’exercice"}],"questions":[{"enonce":"Touche les deux exclamations fausses.","aide":"L’une inverse sujet et verbe ; l’autre emploie le mauvais mot devant un nom.","type":"zone","document":"liste","multiple":true},{"enonce":"Pourquoi « What a mess is this! » est-elle fausse ?","aide":"Compare avec la phrase d’Eli.","type":"choix","options":[{"id":"a","texte":"Sujet et verbe ne s’inversent pas dans une exclamation"},{"id":"b","texte":"Il faut remplacer what par how devant un nom"},{"id":"c","texte":"Le verbe doit être au prétérit dans une exclamation"},{"id":"d","texte":"L’article a est interdit devant le mot mess"}],"multiple":false},{"enonce":"Corrige la phrase de Rita.","aide":"Des fleurs, c’est un nom au pluriel.","type":"trous","segments":[0," nice flowers!"],"banque":["How","What","A","So"]},{"enonce":"Touche les deux mots (adjectif et adverbe) qui suivent so ou how dans la lettre de Rita.","aide":"« Success » est un nom : ne le touche pas.","type":"zone","document":"lettre","multiple":true}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r1c0","r2c0"]},"explication":"**What a mess is this!** (inversion à éviter) et **How nice flowers!** (*how* ne va pas devant un nom)."},{"cle":{"type":"choix","ids":["a"]},"explication":"L’ordre est **sujet puis verbe** (*this is*), contrairement à la question."},{"cle":{"type":"trous","trous":[["what"]]},"affichage":"What","explication":"**What nice flowers!** : *what* devant un nom, sans article au pluriel."},{"cle":{"type":"zone","ids":["m17","m19"]},"explication":"**delicious** (après *so*) et **proudly** (après *how*) : adjectif ou adverbe, pas un nom."}]$ex$::jsonb),
  ('d1a3f12e-fb3b-5157-ad66-9290fe2802f6'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"La vie de Granny Rose","competence":"se-reperer-temps","situation":"Pour le livret de la famille, Léa a tracé la frise de la vie de sa grand-mère, imaginée pour l’exercice. Observe-la.","documents":[{"id":"frise","type":"frise","titre":"Granny Rose’s life","debut":1950,"fin":2020,"pas":10,"periodes":[{"id":"z1","debut":1990,"fin":2015,"nom":"The bakery years","teinte":"ambre"}],"evenements":[{"id":"z2","date":1950,"nom":"Born in Leeds"},{"id":"z3","date":1968,"nom":"Moved to London"},{"id":"z4","date":1975,"nom":"Got married"},{"id":"z5","date":1990,"nom":"Opened a bakery"},{"id":"z6","date":2015,"nom":"Retired"}],"source":"Frise imaginée pour l’exercice"}],"questions":[{"enonce":"Touche l’événement qui s’est passé en 1968.","aide":"Regarde la graduation entre 1960 et 1970.","type":"zone","document":"frise","multiple":false},{"enonce":"Quel âge avait-elle quand elle a ouvert la boulangerie ?","aide":"Soustrais l’année de sa naissance.","type":"nombre","unite":"ans"},{"enonce":"Complète la phrase.","aide":"Un fait daté appelle le prétérit du verbe être.","type":"trous","segments":["She ",0," born in 1950."],"banque":["did","were","is","was"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z3"]},"explication":"En **1968**, Granny Rose *moved to London* : un fait daté, donc le prétérit."},{"cle":{"type":"nombre","valeur":40,"tolerance":0},"affichage":"40 ans","explication":"1990 − 1950 = **40 ans**."},{"cle":{"type":"trous","trous":[["was"]]},"affichage":"was","explication":"**was** : « elle est née en 1950 », prétérit de *be*."}]$ex$::jsonb),
  ('d1a3f12e-fb3b-5157-ad66-9290fe2802f6'::uuid, 2, 2, 10, 35, 5,
   $ex${"titre":"Pourquoi tu n’as pas répondu ?","competence":"manier-langue","situation":"Ana veut savoir pourquoi Ben n’a pas répondu à son appel hier. Observe les deux prétérits de la discussion.","documents":[{"id":"appel","type":"dialogue","modele":"sms","titre":"Messages","participants":[{"nom":"Ana","emoji":"👧","cote":"gauche"},{"nom":"Ben","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Ana","texte":"Why didn’t you answer the phone yesterday?"},{"qui":"Ben","texte":"I was watching a film when you called. Then I went out."},{"qui":"Ana","texte":"Did you see the match last night?"}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche le verbe qui décrit le décor, l’action en cours.","aide":"Il suit *was*.","type":"zone","document":"appel","multiple":false},{"enonce":"Touche le verbe qui décrit l’événement qui interrompt le décor.","aide":"C’est le verbe qui suit *when*.","type":"zone","document":"appel","multiple":false},{"enonce":"Relie chaque verbe à son prétérit.","aide":"Trois de ces prétérits sont irréguliers.","type":"association","gauche":[{"id":"g0","texte":"go"},{"id":"g1","texte":"see"},{"id":"g2","texte":"take"},{"id":"g3","texte":"study"}],"droite":[{"id":"d0","texte":"saw"},{"id":"d1","texte":"went"},{"id":"d2","texte":"studied"},{"id":"d3","texte":"took"}]},{"enonce":"Complète la négation.","aide":"Après *didn’t*, le verbe reste à la base.","type":"trous","segments":["I didn’t ",0," to school yesterday."],"banque":["gone","went","go","going"]},{"enonce":"Ben a vu le match hier soir. Quelle phrase est correcte ?","aide":"Un repère de temps passé comme *last night* appelle le prétérit.","type":"choix","options":[{"id":"a","texte":"I have seen the match last night"},{"id":"b","texte":"I was see the match last night"},{"id":"c","texte":"I saw the match last night"},{"id":"d","texte":"I did saw the match last night"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m9"]},"explication":"**was watching** : le prétérit en BE + -ING décrit l’action en cours, comme l’imparfait."},{"cle":{"type":"zone","ids":["m14"]},"explication":"**called** : le prétérit simple exprime l’événement qui arrive."},{"cle":{"type":"association","paires":{"g1":"d0","g0":"d1","g3":"d2","g2":"d3"}},"explication":"**go → went**, **see → saw**, **take → took** sont irréguliers ; **study → studied** est régulier (y → ied)."},{"cle":{"type":"trous","trous":[["go"]]},"affichage":"go","explication":"**go** : *didn’t* porte la marque du passé, le verbe revient à la base."},{"cle":{"type":"choix","ids":["c"]},"explication":"**I saw the match last night.** : un fait daté ne se met jamais au present perfect."}]$ex$::jsonb),
  ('d1a3f12e-fb3b-5157-ad66-9290fe2802f6'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Alarme au musée","competence":"analyser-document","situation":"Un soir, l’alarme a retenti dans un musée imaginaire. Un agent d’entretien raconte ce qu’il faisait, et le registre de sécurité donne les heures.","documents":[{"id":"temoin","type":"texte","genre":"article","titre":"Mr Hill’s statement","blocs":["Last Friday, I was cleaning the main hall when the alarm rang. I didn’t see anybody, but two guards were talking in the corridor.","The police arrived soon afterwards."],"source":"Témoignage écrit pour l’exercice"},{"id":"registre","type":"tableau","titre":"Security log","colonnes":["Time","Event"],"lignes":[["20:00","The guard started his round"],["20:30","The alarm rang"],["20:45","The police arrived"],["21:30","The museum closed"]],"enteteLignes":true,"source":"Registre inventé pour l’exercice"}],"questions":[{"enonce":"Touche le verbe qui décrit ce que faisait Mr Hill, le décor de la scène.","aide":"Il suit *was* et se termine par -ing.","type":"zone","document":"temoin","multiple":false},{"enonce":"Touche la case qui donne l’heure à laquelle l’alarme a sonné.","aide":"Cherche la ligne « The alarm rang ».","type":"zone","document":"registre","multiple":false},{"enonce":"Combien de minutes se sont écoulées entre l’alarme et l’arrivée de la police ?","aide":"Lis les heures dans le registre.","type":"nombre","unite":"minutes"},{"enonce":"Range chaque verbe du témoignage selon sa forme.","aide":"Un événement qui arrive est au prétérit simple ; une action en cours est en BE + -ING.","type":"categories","categories":[{"id":"c0","texte":"prétérit simple (événement)"},{"id":"c1","texte":"prétérit BE + -ING (décor)"}],"items":[{"id":"i0","texte":"arrived"},{"id":"i1","texte":"was cleaning"},{"id":"i2","texte":"were talking"},{"id":"i3","texte":"didn’t see"},{"id":"i4","texte":"rang"}]},{"enonce":"Mr Hill écrit « the police arrived soon afterwards ». Quelle phrase est incorrecte ?","aide":"Un fait daté ne se met pas au present perfect.","type":"choix","options":[{"id":"a","texte":"The police have arrived at 20:45"},{"id":"b","texte":"The police arrived soon afterwards"},{"id":"c","texte":"The police arrived at 20:45"},{"id":"d","texte":"The police didn’t arrive at 20:30"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m4"]},"explication":"**was cleaning** : le prétérit en BE + -ING décrit l’action en cours au moment où l’alarme sonne."},{"cle":{"type":"zone","ids":["r1c0"]},"explication":"L’alarme a sonné à **20:30**."},{"cle":{"type":"nombre","valeur":15,"tolerance":0},"affichage":"15 minutes","explication":"20:45 − 20:30 = **15 minutes**."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c1","i2":"c1","i3":"c0","i4":"c0"}},"explication":"**rang, arrived, didn’t see** sont des événements ; **was cleaning, were talking** sont le décor, des actions en cours."},{"cle":{"type":"choix","ids":["a"]},"explication":"**The police have arrived at 20:45** est faux : avec une heure précise, on emploie le **prétérit**."}]$ex$::jsonb),
