 ",0," children pay £5."],"banque":["unless","despite","in case","whereas"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r2c0"]},"explication":"**Tess** a un casque et un moniteur : elle remplit les deux conditions."},{"cle":{"type":"zone","ids":["z3"]},"explication":"**although it closes at 6 p.m. on Sundays** : une concession, le mur est ouvert tous les jours malgré cette réserve."},{"cle":{"type":"nombre","valeur":31,"tolerance":0},"affichage":"31 £","explication":"2 × 8 + 3 × 5 = 16 + 15 = **£31**."},{"cle":{"type":"choix","ids":["d"]},"explication":"**unless he wears** : jamais *unless he doesn’t*, la négation serait doublée."},{"cle":{"type":"trous","trous":[["whereas"]]},"affichage":"whereas","explication":"**whereas** exprime une opposition entre deux faits."}]$ex$::jsonb),
