   $ex${"titre":"Le train de Tom est déjà parti","competence":"comprendre-langue","situation":"Tom arrive à la gare : quel dommage ! Lis son histoire et repère ce qui s’est passé avant.","documents":[{"id":"recit","type":"texte","genre":"recit","titre":"A bad morning","blocs":["When Tom arrived at the station, the train had already left. He had overslept and he had missed the early one too.","Then he bought a ticket for the next train."],"source":"Texte écrit pour l’exercice"}],"questions":[{"enonce":"Touche les trois participes passés qui suivent « had ».","aide":"Le prétérit « arrived » et « bought » ne suivent pas had.","type":"zone","document":"recit","multiple":true},{"enonce":"Range ces trois faits dans l’ordre où ils se sont passés.","aide":"Le past perfect marque ce qui s’est passé en premier.","type":"ordre","items":[{"id":"a","texte":"Tom bought a ticket"},{"id":"b","texte":"The train left"},{"id":"c","texte":"Tom arrived at the station"}]},{"enonce":"Complète la phrase.","aide":"Le film a commencé avant notre arrivée.","type":"trous","segments":["When we got home, the film ",0," already started."],"banque":["had","has","did","have"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m10","m13","m17"]},"explication":"Les participes sont **left, overslept, missed** : had + participe passé = past perfect."},{"cle":{"type":"ordre","ids":["b","c","a"]},"explication":"Le train était **déjà parti** (past perfect) quand Tom est arrivé (prétérit), puis il a acheté son billet."},{"cle":{"type":"trous","trous":[["had"]]},"affichage":"had","explication":"**had** + participe : le film avait déjà commencé avant l’arrivée (prétérit *got*)."}]$ex$::jsonb),
  ('b49eef22-c717-5979-8065-33512540d654'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Le message de Zoe, rapporté","competence":"manier-langue","situation":"Zoe envoie trois messages à sa mère. Celle-ci les rapporte ensuite à son père, une semaine plus tard.","documents":[{"id":"sms","type":"dialogue","modele":"sms","titre":"Messages","participants":[{"nom":"Zoe","emoji":"👧","cote":"gauche"},{"nom":"Mum","emoji":"👩","cote":"droite"}],"repliques":[{"qui":"Zoe","texte":"I have finished my essay."},{"qui":"Zoe","texte":"I lost my bag at school."},{"qui":"Zoe","texte":"I have been waiting for the bus."},{"qui":"Mum","texte":"Poor you!"}],"source":"Messages écrits pour l’exercice"},{"id":"note","type":"texte","genre":"lettre","titre":"A note from Mum","blocs":["Dear Zoe, If I had known about your exam, I would have helped you. But nobody told me."],"source":"Texte écrit pour l’exercice"}],"questions":[{"enonce":"Relie chaque message de Zoe à sa version rapportée.","aide":"Au discours indirect, present perfect et prétérit deviennent tous les deux past perfect.","type":"association","gauche":[{"id":"g0","texte":"I have finished my essay."},{"id":"g1","texte":"I lost my bag at school."},{"id":"g2","texte":"I have been waiting for the bus."}],"droite":[{"id":"d0","texte":"She said she had been waiting for the bus."},{"id":"d1","texte":"She said she had finished her essay."},{"id":"d2","texte":"She said she had lost her bag at school."}]},{"enonce":"Rapporte le message sur le sac. Le premier mot est « Zoe ».","aide":"Sujet, verbe de parole, puis la phrase rapportée au past perfect.","type":"ordre","items":[{"id":"a","texte":"lost"},{"id":"b","texte":"had"},{"id":"c","texte":"said"},{"id":"d","texte":"she"},{"id":"e","texte":"her"},{"id":"f","texte":"Zoe"},{"id":"g","texte":"bag"}]},{"enonce":"Touche le participe passé de la subordonnée en « if ».","aide":"Il suit « had » juste après « If I ».","type":"zone","document":"note","multiple":false},{"enonce":"Que dit réellement la phrase de la mère ?","aide":"L’irréel du passé dit le contraire de ce qui s’est passé.","type":"choix","options":[{"id":"a","texte":"Elle ne savait pas et n’a donc pas aidé Zoe"},{"id":"b","texte":"Elle n’a pas voulu aider Zoe pour son examen"},{"id":"c","texte":"Elle aidera Zoe si elle apprend la date"},{"id":"d","texte":"Elle savait pour l’examen et elle a aidé Zoe"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"association","paires":{"g2":"d0","g0":"d1","g1":"d2"}},"explication":"Au discours indirect au passé, le present perfect et le prétérit deviennent un **past perfect** (*had finished*, *had lost*, *had been waiting*)."},{"cle":{"type":"ordre","ids":["f","c","d","b","a","e","g"]},"explication":"**Zoe said she had lost her bag** : le prétérit *lost* devient *had lost*."},{"cle":{"type":"zone","ids":["m5"]},"explication":"C’est **known** : *If I had known…* est un irréel du passé (past perfect après *if*)."},{"cle":{"type":"choix","ids":["a"]},"explication":"**If I had known, I would have helped** signifie : je ne savais pas, donc je n’ai pas aidé."}]$ex$::jsonb),
