   $ex${"titre":"La tempête du vieux phare","competence":"se-reperer-temps","situation":"Dans le village imaginaire de Seaford, un phare a connu quatre événements. Un journaliste raconte la tempête de 2003 en remontant dans le temps.","documents":[{"id":"frise","type":"frise","titre":"The lighthouse timeline","debut":1995,"fin":2010,"pas":5,"evenements":[{"id":"z1","date":1998,"nom":"Keeper retires"},{"id":"z2","date":2001,"nom":"Lamp replaced"},{"id":"z3","date":2003,"nom":"Big storm"},{"id":"z4","date":2005,"nom":"Centre opens"}],"source":"Frise inventée pour l’exercice"},{"id":"article","type":"texte","genre":"article","titre":"Seaford Gazette","blocs":["When the storm hit the coast, Mr Hale had already retired. The council had replaced the lamp two years before, so the lighthouse still worked."],"source":"Article imaginé pour l’exercice"}],"questions":[{"enonce":"Touche l’événement qui correspond à « Mr Hale had already retired ».","aide":"C’est le plus ancien des événements racontés.","type":"zone","document":"frise","multiple":false},{"enonce":"Combien d’années avant la tempête la lampe avait-elle été remplacée ?","aide":"Compare les dates de la frise.","type":"nombre","unite":"ans"},{"enonce":"Complète la phrase d’un visiteur du centre, en 2005.","aide":"On remonte avant 2005 : past perfect.","type":"trous","segments":["When the centre opened, the storm ",0," ",1," the coast two years before."],"banque":["had","has","hit","hitting"]},{"enonce":"Complète la phrase sur le gardien.","aide":"On insiste sur la durée de l’action antérieure.","type":"trous","segments":["In 1999, Mr Hale was exhausted: he ",0," ",1," working for twelve hours."],"banque":["been","was","had","being"]},{"enonce":"Quelle phrase dit que la lampe a été remplacée AVANT la tempête ?","aide":"L’action la plus ancienne se met au past perfect.","type":"choix","options":[{"id":"a","texte":"When the storm hit, the council replaced the lamp."},{"id":"b","texte":"When the storm hit, the council had replaced the lamp."},{"id":"c","texte":"When the storm had hit, the council replaced the lamp."},{"id":"d","texte":"When the storm hit, the council has replaced the lamp."}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z1"]},"explication":"Mr Hale est parti à la retraite en **1998**, bien avant la tempête de 2003."},{"cle":{"type":"nombre","valeur":2,"tolerance":0},"affichage":"2 ans","explication":"2003 − 2001 = **2 ans** : *had replaced … two years before*."},{"cle":{"type":"trous","trous":[["had"],["hit"]]},"affichage":"had · hit","explication":"**had hit** : l’événement est antérieur à l’ouverture du centre (prétérit *opened*)."},{"cle":{"type":"trous","trous":[["had"],["been"]]},"affichage":"had · been","explication":"**had been working** : past perfect en BE + -ING pour la durée avant un état passé (*was exhausted*)."},{"cle":{"type":"choix","ids":["b"]},"explication":"**had replaced** est le fait antérieur ; *hit* au prétérit est le repère."}]$ex$::jsonb),
