  ('8a65c707-5151-57d5-93a7-1058287d17fb'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Le camp d’été de Ruth","competence":"analyser-document","situation":"Ruth écrit à l’organisateur d’un camp. Compare son message avec le règlement affiché.","documents":[{"id":"mail","type":"texte","genre":"lettre","titre":"Dear Mr Hall","blocs":["I’m afraid I can’t come on Saturday: I have to work on Saturdays. My brother might come instead.","He can swim very well. Next year, he will be able to join the older group."],"source":"Courriel écrit pour l’exercice"},{"id":"regles","type":"fiche","modele":"panneau","entete":"Camp Sunshine","sousTitre":"Rules","emoji":"⚠️","lignes":[{"texte":"You must wear a helmet."},{"texte":"You mustn’t touch the fire."},{"texte":"You don’t have to bring food."},{"texte":"You mustn’t leave the camp alone."},{"texte":"You don’t have to sing at the party."},{"texte":"You must tell the guide."}],"pied":"Have fun!","teinte":"jaune","source":"Panneau écrit pour l’exercice"}],"questions":[{"enonce":"Touche le modal qui exprime la capacité.","aide":"Il parle de ce que le frère sait faire.","type":"zone","document":"mail","multiple":false},{"enonce":"Ruth écrit « I have to work on Saturdays ». Pourquoi pas « I must work » ?","aide":"Qui décide qu’elle doit travailler : elle ou sa situation ?","type":"choix","options":[{"id":"a","texte":"Parce que « must » ne se met jamais à la première personne"},{"id":"b","texte":"Parce que « work » est un verbe à particule"},{"id":"c","texte":"Parce que « have to » exprime une déduction"},{"id":"d","texte":"L’obligation vient des circonstances (son travail), pas de sa décision"}],"multiple":false},{"enonce":"Complète la phrase de Ruth.","aide":"Deux modaux ne se suivent pas : on emprunte une autre forme.","type":"trous","segments":["Next year, he will ",0," able to join the older group."],"banque":["is","can","be","have"]},{"enonce":"Range les phrases du règlement.","aide":"Ne confonds pas « il ne faut pas » et « ce n’est pas la peine ».","type":"categories","categories":[{"id":"c0","texte":"obligation (must)"},{"id":"c1","texte":"interdiction (mustn’t)"},{"id":"c2","texte":"pas obligé (don’t have to)"}],"items":[{"id":"i0","texte":"You must wear a helmet."},{"id":"i1","texte":"You don’t have to bring food."},{"id":"i2","texte":"You must tell the guide."},{"id":"i3","texte":"You don’t have to sing at the party."},{"id":"i4","texte":"You mustn’t leave the camp alone."},{"id":"i5","texte":"You mustn’t touch the fire."}]}]}$ex$::jsonb,
