  ('bb86d76e-ec3e-55ba-88e3-a7652920e119'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Ce que Lucy a dit à Max","competence":"comprendre-langue","situation":"Lucy a dit trois choses à Max pendant la récréation. Max les répète à Sam, mais au passé : le tableau met les paroles de Lucy en face de ce que Max rapporte.","documents":[{"id":"paroles","type":"tableau","titre":"Lucy’s words","colonnes":["Lucy said:","Max told Sam:"],"lignes":[["“I am hungry.”","Lucy said she was hungry."],["“I like this song.”","Lucy said she liked that song."],["“I have finished.”","Lucy said she had finished."]],"source":"Tableau écrit pour l’exercice"}],"questions":[{"enonce":"Touche la case où « am » est devenu « was » au discours indirect.","aide":"Cherche la phrase de la colonne de droite qui correspond à « I am hungry ».","type":"zone","document":"paroles","multiple":false},{"enonce":"Complète le discours indirect de « I will win. »","aide":"Au discours indirect passé, *will* devient son équivalent au passé.","type":"trous","segments":["Lucy said she ",0," win."],"banque":["is","would","was","has"]},{"enonce":"Quelle phrase est correcte ?","aide":"Un seul des deux verbes (*say* ou *tell*) accepte un complément de personne juste après lui.","type":"choix","options":[{"id":"a","texte":"Lucy told me that she was hungry."},{"id":"b","texte":"Lucy said me she hungry."},{"id":"c","texte":"Lucy told that she was hungry."},{"id":"d","texte":"Lucy said me that she was hungry."}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r0c1"]},"explication":"**Lucy said she was hungry** : un présent (*am*) recule d’un cran et devient un prétérit (*was*)."},{"cle":{"type":"trous","trous":[["would"]]},"affichage":"would","explication":"**would** : *will* devient *would* quand le verbe introducteur est au passé."},{"cle":{"type":"choix","ids":["a"]},"explication":"**Lucy told me that she was hungry.** : *tell* exige un complément de personne, *say* n’en a jamais (*said me* est une faute lourde)."}]$ex$::jsonb),
  ('bb86d76e-ec3e-55ba-88e3-a7652920e119'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Les consignes de Mr Ellis","competence":"manier-langue","situation":"Lundi, Mr Ellis a donné des consignes à la classe 2B, puis il a posé deux questions. Elena les rapporte à une camarade absente.","documents":[{"id":"consignes","type":"fiche","modele":"affiche","entete":"Mr Ellis, class 2B","sousTitre":"What he said on Monday","emoji":"📚","lignes":[{"texte":"“Open your books.”","id":"z1"},{"texte":"“Don’t talk during the test.”","id":"z2"},{"texte":"“Where is your homework?”","id":"z3"},{"texte":"“Do you understand?”","id":"z4"}],"source":"Affiche écrite pour l’exercice"}],"questions":[{"enonce":"Touche la phrase qui, rapportée, s’introduit par « if » (il n’y a pas de mot interrogatif).","aide":"Une question sans mot interrogatif (*where, what…*) s’introduit par *if* ou *whether*.","type":"zone","document":"consignes","multiple":false},{"enonce":"Rapporte la question « Where is your homework? » Le premier mot est « He ».","aide":"Plus d’inversion ni de *do*, le verbe recule d’un cran et le pronom s’adapte.","type":"ordre","items":[{"id":"a","texte":"our"},{"id":"b","texte":"where"},{"id":"c","texte":"homework"},{"id":"d","texte":"asked"},{"id":"e","texte":"He"},{"id":"f","texte":"was"}]},{"enonce":"Rapporte l’ordre négatif « Don’t talk. »","aide":"Un ordre négatif se rapporte avec un infinitif négatif.","type":"trous","segments":["He told us ",0," to talk during the test."],"banque":["no","doesn’t","don’t","not"]},{"enonce":"Relie chaque phrase de Mr Ellis à sa version rapportée.","aide":"Ordre : *told us (not) to* ; question avec mot interrogatif : *asked where* ; question fermée : *asked if*.","type":"association","gauche":[{"id":"g0","texte":"“Open your books.”"},{"id":"g1","texte":"“Don’t talk during the test.”"},{"id":"g2","texte":"“Where is your homework?”"},{"id":"g3","texte":"“Do you understand?”"}],"droite":[{"id":"d0","texte":"He asked where our homework was."},{"id":"d1","texte":"He told us not to talk during the test."},{"id":"d2","texte":"He told us to open our books."},{"id":"d3","texte":"He asked if we understood."}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z4"]},"explication":"**“Do you understand?”** : question fermée, donc *He asked if we understood*."},{"cle":{"type":"ordre","ids":["e","d","b","a","c","f"]},"explication":"**He asked where our homework was** : pas d’inversion, *is* devient *was*, *your* devient *our*."},{"cle":{"type":"trous","trous":[["not"]]},"affichage":"not","explication":"**not** : un ordre négatif devient *not to* + base verbale (*He told us not to talk*)."},{"cle":{"type":"association","paires":{"g2":"d0","g1":"d1","g0":"d2","g3":"d3"}},"explication":"Ordre : infinitif (*told us to / not to*) ; question : *asked where…* sans inversion, ou *asked if…* quand il n’y a pas de mot interrogatif."}]$ex$::jsonb),
  ('bb86d76e-ec3e-55ba-88e3-a7652920e119'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"L’interview avant le festival","competence":"analyser-document","situation":"Une journaliste du lycée a interviewé le directeur du festival de musique. Elle a rédigé un brouillon rapportant l’interview, mais il contient deux fautes de discours indirect. À toi de les trouver.","documents":[{"id":"interview","type":"dialogue","modele":"sms","titre":"The interview","participants":[{"nom":"Reporter","emoji":"🎤","cote":"gauche"},{"nom":"Director","emoji":"🎪","cote":"droite"}],"repliques":[{"qui":"Reporter","texte":"How do you feel today?"},{"qui":"Director","texte":"We are very excited today. We have sold 5,000 tickets, and we will open the gates tomorrow."},{"qui":"Reporter","texte":"Do you expect rain?"},{"qui":"Director","texte":"Not at all!"}],"source":"Interview écrite pour l’exercice"},{"id":"brouillon","type":"texte","genre":"article","titre":"The journalist’s draft","blocs":["The director said me that they were very excited. He said they had sold 5,000 tickets and that they would open the gates.","I asked him did he expect rain. He answered that he was sure the weather would be fine."],"source":"Brouillon écrit pour l’exercice"}],"questions":[{"enonce":"Touche le mot en trop dans la première phrase : *say* n’a pas de complément de personne.","aide":"Cherche un pronom qui suit directement *said*.","type":"zone","document":"brouillon","multiple":false},{"enonce":"Touche l’auxiliaire qui n’a rien à faire dans une question indirecte.","aide":"Dans une question indirecte, il n’y a ni inversion ni *do*.","type":"zone","document":"brouillon","multiple":false},{"enonce":"Rapporte « we will open the gates tomorrow ».","aide":"Au discours indirect passé, *tomorrow* change de forme.","type":"trous","segments":["He said they would open the gates ",0,"."],"banque":["the day before","the next day","tomorrow","then"]},{"enonce":"Écris la bonne version de la question de la journaliste. Le premier mot est « I ».","aide":"Question fermée : *if* ; le verbe recule d’un cran, sans *do*.","type":"ordre","items":[{"id":"a","texte":"expected"},{"id":"b","texte":"I"},{"id":"c","texte":"asked"},{"id":"d","texte":"he"},{"id":"e","texte":"if"},{"id":"f","texte":"rain"},{"id":"g","texte":"him"}]},{"enonce":"Relie chaque mot du discours direct à sa forme au discours indirect.","aide":"Tout se déplace d’un cran vers le passé et vers l’éloignement.","type":"association","gauche":[{"id":"g0","texte":"will"},{"id":"g1","texte":"must"},{"id":"g2","texte":"tomorrow"},{"id":"g3","texte":"yesterday"},{"id":"g4","texte":"here"}],"droite":[{"id":"d0","texte":"there"},{"id":"d1","texte":"would"},{"id":"d2","texte":"the next day"},{"id":"d3","texte":"had to"},{"id":"d4","texte":"the day before"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m3"]},"explication":"**said me** est une faute : *say* ne prend pas de complément de personne (*He said that…* ou *He told me that…*)."},{"cle":{"type":"zone","ids":["m27"]},"explication":"**did** est en trop : la question indirecte s’écrit *I asked him if he expected rain*, sans *do*."},{"cle":{"type":"trous","trous":[["the next day"]]},"affichage":"the next day","explication":"**the next day** : *tomorrow* devient *the next day* au discours indirect passé."},{"cle":{"type":"ordre","ids":["b","c","g","e","d","a","f"]},"explication":"**I asked him if he expected rain** : *if*, pas d’inversion et *expect* devient *expected*."},{"cle":{"type":"association","paires":{"g4":"d0","g0":"d1","g2":"d2","g1":"d3","g3":"d4"}},"explication":"*Will* devient *would*, *must* devient *had to*, *tomorrow* devient *the next day*, *yesterday* devient *the day before*, *here* devient *there*."}]$ex$::jsonb),
  ('de6d964c-a7ff-5296-bfc5-8306422a3772'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"La voisine, le chien et le café","competence":"comprendre-langue","situation":"Une lycéenne présente son quartier dans un petit texte. Repère les pronoms relatifs.","documents":[{"id":"texte","type":"texte","genre":"article","titre":"My neighbourhood","blocs":["The girl who lives next door has a dog which barks all day. This is the café where we met. My brother, whose phone is broken, sits beside me."],"source":"Texte écrit pour l’exercice"}],"questions":[{"enonce":"Touche les quatre pronoms relatifs du texte.","aide":"Ils relient un nom à une proposition : une personne, une chose, un lieu, un possesseur.","type":"zone","document":"texte","multiple":true},{"enonce":"Relie chaque relatif à ce qu’il reprend.","aide":"Pense au nom placé juste avant : girl, dog, brother, café.","type":"association","gauche":[{"id":"g0","texte":"who"},{"id":"g1","texte":"which"},{"id":"g2","texte":"whose"},{"id":"g3","texte":"where"}],"droite":[{"id":"d0","texte":"une personne"},{"id":"d1","texte":"une chose"},{"id":"d2","texte":"un lieu"},{"id":"d3","texte":"un possesseur"}]},{"enonce":"Complète la phrase.","aide":"Le nom « friend » désigne une personne.","type":"trous","segments":["I have a friend ",0," lives in Wales."],"banque":["which","who","where","whose"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m2","m9","m17","m22"]},"explication":"Les relatifs sont **who, which, where, whose**."},{"cle":{"type":"association","paires":{"g0":"d0","g1":"d1","g3":"d2","g2":"d3"}},"explication":"**who** = personne, **which** = chose, **whose** = possesseur (« dont »), **where** = lieu."},{"cle":{"type":"trous","trous":[["who"]]},"affichage":"who","explication":"**who** : relatif sujet qui reprend une personne."}]$ex$::jsonb),
