  ('de6d964c-a7ff-5296-bfc5-8306422a3772'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"La visite du musée","competence":"analyser-document","situation":"La classe de M. Cole prépare une visite au musée. Un article de l’école et l’affiche du musée donnent les consignes.","documents":[{"id":"article","type":"texte","genre":"article","titre":"School news","blocs":["On Monday, Mr Cole told the class that the trip would take place on Friday. He said he hoped everybody would bring a packed lunch. The pupils will phone the museum as soon as the coach arrives, because they want to check the opening hours."],"source":"Article imaginé pour l’exercice"},{"id":"affiche","type":"fiche","modele":"affiche","entete":"City Museum","sousTitre":"Open 9 a.m. – 5 p.m.","emoji":"🏛️","lignes":[{"texte":"Open until 5 p.m., although the café closes at four.","id":"z1"},{"texte":"Photos are forbidden unless a guide agrees.","id":"z2"},{"texte":"Please queue here so that everyone can enter.","id":"z3"}],"source":"Affiche imaginée pour l’exercice"}],"questions":[{"enonce":"Touche le verbe au présent qui exprime un futur après « as soon as ».","aide":"Après as soon as, jamais will.","type":"zone","document":"article","multiple":false},{"enonce":"Complète la phrase de l’article.","aide":"Le complément est une personne : the class.","type":"trous","segments":["Mr Cole ",0," the class that the trip would take place on Friday."],"banque":["say","tell","said","told"]},{"enonce":"Touche la règle qui exprime un but.","aide":"Cherche l’expression « afin que ».","type":"zone","document":"affiche","multiple":false},{"enonce":"Relie chaque conjonction à la relation qu’elle exprime.","aide":"Relis les trois règles de l’affiche pour retrouver le sens.","type":"association","gauche":[{"id":"g0","texte":"although"},{"id":"g1","texte":"unless"},{"id":"g2","texte":"so that"},{"id":"g3","texte":"because"}],"droite":[{"id":"d0","texte":"une concession"},{"id":"d1","texte":"un but"},{"id":"d2","texte":"une condition négative"},{"id":"d3","texte":"une cause"}]},{"enonce":"Que signifie « Photos are forbidden unless a guide agrees » ?","aide":"Unless contient déjà une négation : « si … ne … pas ».","type":"choix","options":[{"id":"a","texte":"Les photos sont interdites parce qu’un guide est présent"},{"id":"b","texte":"Les photos sont interdites même si un guide est d’accord"},{"id":"c","texte":"Les photos sont autorisées dès qu’un guide est présent"},{"id":"d","texte":"Les photos sont interdites sauf si un guide est d’accord"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m36"]},"explication":"**arrives** : après une conjonction de temps, on emploie le présent."},{"cle":{"type":"trous","trous":[["told"]]},"affichage":"told","explication":"**told** : *tell* exige un complément de personne ; *said the class that* est faux."},{"cle":{"type":"zone","ids":["z3"]},"explication":"**so that everyone can enter** : *so that* + proposition exprime le but."},{"cle":{"type":"association","paires":{"g0":"d0","g2":"d1","g1":"d2","g3":"d3"}},"explication":"**although** = concession, **unless** = à moins que, **so that** = but, **because** = cause."},{"cle":{"type":"choix","ids":["d"]},"explication":"**unless** = « sauf si, à moins que » : l’accord du guide lève l’interdiction."}]$ex$::jsonb),
