   $ex${"titre":"Une affiche en calques, une photo truquée","competence":"analyser-document","situation":"Zoé monte l’affiche du festival en plusieurs calques. Le journal du lycée, lui, reçoit une photographie d’inondation qui circule beaucoup. Les deux cas posent la même question : que vaut une image retouchée ?","documents":[{"id":"calques","type":"schema","titre":"Les calques de l’affiche","largeur":320,"hauteur":220,"elements":[{"forme":"texte","x":14,"y":22,"texte":"Du dessus vers le dessous","taille":"petit","italique":true,"ancre":"debut"},{"forme":"rect","x":14,"y":34,"l":292,"h":34,"teinte":"violet","motif":"clair","texte":"Calque 4 · texte « FESTIVAL »","id":"z1","zone":true},{"forme":"rect","x":14,"y":74,"l":292,"h":34,"teinte":"turquoise","motif":"clair","texte":"Calque 3 · danseuse détourée (PNG)","id":"z2","zone":true},{"forme":"rect","x":14,"y":114,"l":292,"h":34,"teinte":"ambre","motif":"clair","texte":"Calque 2 · dégradé orange","id":"z3","zone":true},{"forme":"rect","x":14,"y":154,"l":292,"h":34,"teinte":"gris","motif":"clair","texte":"Calque 1 · photo de la scène","id":"z4","zone":true}]},{"id":"article","type":"texte","genre":"article","titre":"La photo d’inondation","auteur":"Texte écrit pour l’exercice","blocs":["Samedi, une photographie montrant une rue inondée, avec un chien sur le toit d’une voiture, est partagée des milliers de fois.","La rédaction du journal du lycée l’examine. Le fichier est un JPEG dont les informations d’origine ont été effacées. En l’agrandissant, on découvre des bords trop nets autour du chien : l’image a été assemblée à partir de deux photographies.","Le résultat est pourtant très réussi : à l’œil nu, rien ne le trahit."],"source":"Texte écrit pour l’exercice"}],"questions":[{"enonce":"Zoé veut changer le mot de l’affiche sans toucher au reste. Touche **le calque à modifier**.","aide":"Chaque élément vit sur son propre calque : lequel contient le mot ?","type":"zone","document":"calques","multiple":false},{"enonce":"Touche **le calque d’une image détourée qui garde sa transparence**.","aide":"Un détourage laisse un fond transparent : quel format le permet ?","type":"zone","document":"calques","multiple":false},{"enonce":"Que reste-t-il de la valeur de preuve de la photo d’inondation ?","aide":"La retouche ne laisse plus de trace visible : que faut-il donc vérifier ailleurs ?","type":"choix","options":[{"id":"a","texte":"Elle ne suffit plus : il faut recouper source, date et autres images"},{"id":"b","texte":"Elle prouve tout, car c’est un fichier numérique très précis"},{"id":"c","texte":"Elle ne prouve rien du tout, il faut donc la détruire vite"},{"id":"d","texte":"Elle reste une preuve, puisque le résultat est parfait à l’œil nu"}],"multiple":false},{"enonce":"Complète la phrase sur l’œuvre reproductible.","aide":"Benjamin parle d’une présence unique, qu’il appelle « aura ».","type":"trous","segments":["En 1935, Walter Benjamin annonce que la reproduction fait perdre à l’œuvre son ",0,", c’est-à-dire son ",1,"."],"banque":["format","aura","ici-et-maintenant","auteur","prix"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z1"]},"explication":"Le **calque 4** contient le texte. Les calques servent à superposer et à modifier des éléments **indépendamment**, sans abîmer le reste."},{"cle":{"type":"zone","ids":["z2"]},"explication":"Le **calque 3** porte la danseuse détourée, en **PNG** : ce format garde la transparence, donc le fond de scène reste visible autour d’elle."},{"cle":{"type":"choix","ids":["a"]},"explication":"Une photographie numérique **n’est pas toujours une preuve fiable** : le montage permet des images sans référent réel. Il faut croiser la source, la date et d’autres documents."},{"cle":{"type":"trous","trous":[["aura"],["ici et maintenant","presence unique"]]},"affichage":"aura · ici-et-maintenant","explication":"La reproduction fait perdre à l’œuvre son **aura**, son **ici-et-maintenant**, sa présence unique. Le numérique pousse cette logique à l’extrême."}]$ex$::jsonb),
