motif":"clair","texte":"reproductible","id":"z4","zone":true}]}],"questions":[{"enonce":"Dans une **performance**, l’œuvre passe de l’objet à… Touche la case d’arrivée.","aide":"Suis la flèche qui porte le mot « Performance ».","type":"zone","document":"sch","multiple":false},{"enonce":"Touche **la case d’arrivée du déplacement où la copie n’est plus un défaut**.","aide":"Pense à la sérigraphie et à Andy Warhol.","type":"zone","document":"sch","multiple":false},{"enonce":"Relie chaque artiste au geste qui le caractérise.","aide":"Pense à « emballer » pour Christo et Jeanne-Claude, à « enquêter » pour Sophie Calle.","type":"association","gauche":[{"id":"g0","texte":"Andy Warhol"},{"id":"g1","texte":"Christo et Jeanne-Claude"},{"id":"g2","texte":"Sophie Calle"},{"id":"g3","texte":"Ai Weiwei"}],"droite":[{"id":"d0","texte":"La reproduction sérielle"},{"id":"d1","texte":"L’art politique"},{"id":"d2","texte":"L’emballage monumental"},{"id":"d3","texte":"Le récit et l’enquête"}]}]}$ex$::jsonb,
