   $ex${"titre":"Deux cartels imaginaires","competence":"analyser-document","situation":"Au musée, Théo lit deux cartels d’œuvres imaginées pour l’exercice. Un visiteur lui dit devant la première : « Il n’y a rien à voir ! » Théo cherche comment les comprendre.","documents":[{"id":"a","type":"fiche","modele":"etiquette","titre":"Cartel A","entete":"Protocole pour une attente","sousTitre":"Inès Roche (artiste imaginaire), 2021","emoji":"🚉","lignes":[{"texte":"Instructions : s’asseoir trois heures dans une gare, sans rien faire.","id":"z1"},{"texte":"Matériel : aucun.","id":"z2"},{"texte":"Exposé : une photographie et les instructions.","id":"z3"}],"pied":"Œuvre imaginée pour l’exercice"},{"id":"b","type":"fiche","modele":"etiquette","titre":"Cartel B","entete":"Le Pont de toile","sousTitre":"Duo Verdier & Moreau (artistes imaginaires), 2022","emoji":"🌉","lignes":[{"texte":"Lieu : le pont d’une petite ville, sur la rivière.","id":"z4"},{"texte":"Matériaux : 4 000 m² de toile blanche.","id":"z5"},{"texte":"Durée : douze jours, puis démontage.","id":"z6"}],"pied":"Œuvre imaginée pour l’exercice"}],"questions":[{"enonce":"Touche **la ligne du cartel A qui prouve qu’aucun objet n’est fabriqué**.","aide":"Cherche la ligne qui parle des matériaux.","type":"zone","document":"a","multiple":false},{"enonce":"Touche **la ligne du cartel B qui montre que l’œuvre tient à son site**.","aide":"Une œuvre in situ dépend du lieu où elle est installée.","type":"zone","document":"b","multiple":false},{"enonce":"Quelle phrase décrit quel cartel ?","aide":"Le cartel A est une idée à exécuter ; le cartel B est une œuvre posée dans un lieu.","type":"categories","categories":[{"id":"c0","texte":"Cartel A"},{"id":"c1","texte":"Cartel B"}],"items":[{"id":"i0","texte":"Elle est démontée au bout de douze jours"},{"id":"i1","texte":"Le protocole vaut l’œuvre"},{"id":"i2","texte":"L’œuvre tient à son site"},{"id":"i3","texte":"Elle est montrée dans l’espace public"},{"id":"i4","texte":"Les instructions suffisent à la rejouer"},{"id":"i5","texte":"Il n’y a pas d’objet à posséder"}]},{"enonce":"Devant le cartel A, le visiteur dit « Il n’y a rien à voir ! ». Quelle est la meilleure première question à poser ?","aide":"Devant une œuvre qui déroute, on ne demande pas ce qu’elle représente.","type":"choix","options":[{"id":"a","texte":"Que me demande-t-elle de faire ?"},{"id":"b","texte":"Combien a-t-elle coûté à produire ?"},{"id":"c","texte":"Est-ce que c’est beau ?"},{"id":"d","texte":"Un enfant saurait-il la faire ?"}],"multiple":false}]}$ex$::jsonb,
