  ('420b6fbd-bdee-5f71-81f4-ace095f63dba'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Combien vaut une œuvre ?","competence":"lire-graphique","situation":"Dans une galerie, un visiteur s’indigne : les matériaux d’une œuvre ne coûtent presque rien, et pourtant elle se vend très cher. Un graphique imaginé pour l’exercice suit le prix de la même œuvre, étape après étape.","documents":[{"id":"graph","type":"graphique","forme":"barres","titre":"Une œuvre, quatre étapes","categories":["Atelier","Galerie","Foire","Musée"],"series":[{"nom":"Prix de vente (€)","valeurs":[500,3000,12000,40000],"teinte":"violet"},{"nom":"Coût des matériaux (€)","valeurs":[200,200,200,200],"teinte":"sable"}],"axeY":{"titre":"Euros","unite":"€","min":0,"max":40000,"pas":10000},"axeX":{"titre":"Étape du circuit"},"valeurs":false,"source":"Chiffres imaginés pour l’exercice"},{"id":"dialogue","type":"texte","genre":"theatre","titre":"Devant l’œuvre","auteur":"Dialogue écrit pour l’exercice","blocs":[{"personnage":"Visiteur","replique":"Deux cents euros de matériaux, et on la vend quarante mille ? C’est absurde."},{"personnage":"Médiatrice","replique":"Les matériaux n’ont pas changé. Ce qui a changé, c’est le regard posé sur l’œuvre à chaque étape."}]}],"questions":[{"enonce":"Touche **l’étape où le prix de vente augmente le plus** par rapport à l’étape précédente.","aide":"Compare la hausse entre chaque étape et la précédente : la plus grande est la plus visible.","type":"zone","document":"graph","multiple":false},{"enonce":"En galerie, le prix de vente vaut combien de fois le coût des matériaux ?","aide":"Divise le prix de vente en galerie par le coût des matériaux.","type":"nombre","unite":"fois"},{"enonce":"Que montre le graphique ?","aide":"Regarde la série du coût des matériaux : varie-t-elle ?","type":"choix","options":[{"id":"a","texte":"Le musée vend l’œuvre moins cher que ne le fait l’atelier"},{"id":"b","texte":"Le prix de vente suit exactement le coût des matériaux"},{"id":"c","texte":"Les matériaux ne changent pas : la valeur se construit ailleurs"},{"id":"d","texte":"Le prix est fixé une fois pour toutes dans l’atelier"}],"multiple":false},{"enonce":"Complète la réponse de la médiatrice.","aide":"Reprends les étapes du graphique : atelier, galerie, foire, …","type":"trous","segments":["La valeur d’une œuvre se construit ",0," : galeries, foires, biennales et ",1,"."],"banque":["socialement","ateliers","matériaux","musées","techniquement"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["k3"]},"explication":"Entre la foire (12 000 €) et le musée (40 000 €), le prix augmente de **28 000 €**, bien plus qu’aux étapes précédentes (+2 500 €, puis +9 000 €)."},{"cle":{"type":"nombre","valeur":15,"tolerance":0},"affichage":"15 fois","explication":"3 000 ÷ 200 = **15 fois**. La différence ne vient pas des matériaux."},{"cle":{"type":"choix","ids":["c"]},"explication":"Les matériaux restent à 200 € ; le prix monte avec la **galerie, la foire, le musée**. La valeur d’une œuvre contemporaine se construit aussi socialement."},{"cle":{"type":"trous","trous":[["socialement","aussi socialement"],["musees","musee","les musees"]]},"affichage":"socialement · musées","explication":"La valeur se construit **socialement**, par un circuit : galeries, foires, biennales et **musées**. Le comprendre fait partie de la compréhension de l’œuvre."}]$ex$::jsonb),
  ('e3391291-e0ad-5741-b1c9-6210d756ffc8'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Le carnet de recherche d’Ambre","competence":"lire-tableau","situation":"Ambre prépare un projet sur la disparition. Elle tient un carnet de recherche : essais, références, intentions. Le jury lira ce carnet avant même de regarder sa production.","documents":[{"id":"carnet","type":"tableau","titre":"Le carnet d’Ambre","colonnes":["Date","Entrée du carnet"],"lignes":[["3 oct.","Intention : « je veux rendre visible la disparition »"],["10 oct.","Essai 1 raté : encre trop diluée, le papier gondole"],["17 oct.","Référence annotée : une affiche déchirée vue au musée"],["24 oct.","Essai 2 : couches de papier calque, la forme s’efface"]],"enteteLignes":true}],"questions":[{"enonce":"Touche **l’entrée qui formule l’intention** du projet.","aide":"Une intention s’écrit comme une phrase : « je veux… ».","type":"zone","document":"carnet","multiple":false},{"enonce":"Touche **l’essai raté**.","aide":"Cherche l’entrée où quelque chose n’a pas fonctionné.","type":"zone","document":"carnet","multiple":false},{"enonce":"Combien de jours séparent l’intention de l’essai 2 ?","aide":"Lis les deux dates dans la première colonne, puis soustrais.","type":"nombre","unite":"jours"},{"enonce":"Relie chaque élément du carnet à ce qu’il prouve au jury.","aide":"Le carnet est une preuve : chaque trace montre un aspect de la démarche.","type":"association","gauche":[{"id":"g0","texte":"Des croquis et des variantes"},{"id":"g1","texte":"Des essais ratés, datés"},{"id":"g2","texte":"Des références annotées"},{"id":"g3","texte":"Des notes d’intention"}],"droite":[{"id":"d0","texte":"Que la démarche est consciente"},{"id":"d1","texte":"Que des choix ont été écartés"},{"id":"d2","texte":"Que la recherche a eu lieu"},{"id":"d3","texte":"Que le travail se situe"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r0c1"]},"explication":"L’entrée du **3 octobre** formule l’intention : « je veux rendre visible la disparition ». C’est une phrase, pas un simple thème."},{"cle":{"type":"zone","ids":["r1c1"]},"explication":"L’**essai 1** a raté (encre trop diluée). Il reste dans le carnet : un échec daté prouve que la recherche a eu lieu."},{"cle":{"type":"nombre","valeur":21,"tolerance":0},"affichage":"21 jours","explication":"Du 3 octobre au 24 octobre : 24 − 3 = **21 jours**."},{"cle":{"type":"association","paires":{"g3":"d0","g0":"d1","g1":"d2","g2":"d3"}},"explication":"**Croquis** : des choix écartés ; **essais ratés** : la recherche a eu lieu ; **références** : le travail se situe ; **notes d’intention** : la démarche est consciente."}]$ex$::jsonb),
  ('e3391291-e0ad-5741-b1c9-6210d756ffc8'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"La note d’intention de Malik","competence":"analyser-document","situation":"Malik, en seconde, présente une installation. Sa professeure lui demande de distinguer, dans sa note d’intention, le thème, l’intention et la consigne reçue, puis de nommer sa relation à une référence.","documents":[{"id":"note","type":"fiche","modele":"panneau","titre":"Note d’intention","entete":"Sous la table","sousTitre":"Malik, classe de seconde","emoji":"🪑","lignes":[{"texte":"Thème : le sentiment d’être de trop.","id":"z1"},{"texte":"Je veux que le spectateur hésite avant de s’asseoir.","id":"z2"},{"texte":"Consigne reçue : une installation de 2 m² au plus.","id":"z3"},{"separateur":true},{"texte":"Référence : je reprends le dispositif d’une chaise-piège pour en renverser le sens : ici, c’est l’absence de chaise qui invite.","id":"z4"}],"pied":"Note imaginée pour l’exercice"}],"questions":[{"enonce":"Touche **la ligne qui formule une intention** (et pas seulement un thème).","aide":"Une intention dit ce que l’on veut produire sur le spectateur.","type":"zone","document":"note","multiple":false},{"enonce":"Malik reprend un dispositif pour en renverser le sens. Touche **la ligne où il contredit sa référence**.","aide":"Cherche la ligne qui parle d’un dispositif repris.","type":"zone","document":"note","multiple":false},{"enonce":"Range chaque phrase : est-ce un thème, une intention ou une consigne ?","aide":"Un thème est un sujet ; une intention commence par « je veux » ; une consigne vient de l’extérieur.","type":"categories","categories":[{"id":"c0","texte":"Un thème"},{"id":"c1","texte":"Une intention"},{"id":"c2","texte":"Une consigne"}],"items":[{"id":"i0","texte":"Je veux que l’on ose toucher l’œuvre"},{"id":"i1","texte":"Utiliser uniquement du carton"},{"id":"i2","texte":"L’abandon"},{"id":"i3","texte":"Je veux que le spectateur doute de ce qu’il voit"},{"id":"i4","texte":"Le temps qui passe"},{"id":"i5","texte":"Faire une sculpture de moins d’un mètre"}]},{"enonce":"Laquelle de ces formulations est une vraie problématique ?","aide":"Une problématique admet plusieurs réponses plastiques ; une consigne n’en admet qu’une.","type":"choix","options":[{"id":"a","texte":"Dessiner une table et une chaise dans une pièce vide"},{"id":"b","texte":"Réaliser une installation en carton sur le thème de la chaise"},{"id":"c","texte":"Comment peindre une chaise bleue de quarante centimètres ?"},{"id":"d","texte":"Comment faire hésiter le spectateur sans rien lui interdire ?"}],"multiple":false}]}$ex$::jsonb,
